  window.__DATA__["QUIZZES_DATA"] = {"quizzes":[{"id":"ch1-1.1-q1","chapter":"ch1","section":"1.1","type":"single","difficulty":1,"question":"AI Agent 的三个核心要素是什么？","options":[{"key":"A","text":"LLM + 数据库 + 前端界面"},{"key":"B","text":"LLM + 工具 + 循环决策","correct":true},{"key":"C","text":"模型 + 训练数据 + 评估指标"},{"key":"D","text":"API + 服务器 + 客户端"}],"explanation":"Agent = LLM（大脑）+ 工具（手）+ 循环决策（自主性）。三者缺一不可，共同构成 Agent 的完整能力。"},{"id":"ch1-1.1-q2","chapter":"ch1","section":"1.1","type":"single","difficulty":2,"question":"Agent 与 Workflow 的本质区别是什么？","options":[{"key":"A","text":"Agent 使用 LLM，Workflow 不使用"},{"key":"B","text":"Agent 路径动态，Workflow 路径固定","correct":true},{"key":"C","text":"Agent 可以调用 API，Workflow 不可以"},{"key":"D","text":"Agent 比 Workflow 更快"}],"explanation":"Agent 的本质特征是路径的动态性——同一个任务可能根据中间结果走完全不同的路径。而 Workflow 的路径是预先确定的。"},{"id":"ch1-1.1-q3","chapter":"ch1","section":"1.1","type":"multiple","difficulty":2,"question":"以下哪些是 Agent 应具备的能力？（多选）","options":[{"key":"A","text":"感知能力（理解输入）","correct":true},{"key":"B","text":"推理能力（逻辑思考）","correct":true},{"key":"C","text":"行动能力（调用工具）","correct":true},{"key":"D","text":"自主决策（决定下一步）","correct":true}],"explanation":"真正的 Agent 应具备感知、推理、行动、记忆和自主决策五种核心能力。"},{"id":"ch1-1.2-q1","chapter":"ch1","section":"1.2","type":"single","difficulty":1,"question":"GPT-5 的 Context Window 是多少？","options":[{"key":"A","text":"128K"},{"key":"B","text":"200K"},{"key":"C","text":"400K","correct":true},{"key":"D","text":"1M"}],"explanation":"GPT-5 的 Context Window 为 400K Token（输入 272K + 输出 128K），Claude Opus 4.8 为 1M，Gemini 3.5 可达 1M+。"},{"id":"ch1-1.2-q2","chapter":"ch1","section":"1.2","type":"single","difficulty":1,"question":"在 Agent 开发中，代码生成场景应使用什么 Temperature？","options":[{"key":"A","text":"0（确定性）","correct":true},{"key":"B","text":"0.3"},{"key":"C","text":"0.7"},{"key":"D","text":"1.5"}],"explanation":"代码生成必须使用 Temperature=0 保证输出一致性。客服场景可用 0.3，创意场景可用 0.9。"},{"id":"ch1-1.2-q3","chapter":"ch1","section":"1.2","type":"fill","difficulty":2,"question":"1000 字中文大约消耗多少 Token？","answer":"1000-2000","acceptAnswers":["1000-2000","1000","2000","1500"],"explanation":"中文约 1 个汉字 ≈ 1-2 Token，因此 1000 字中文约消耗 1000-2000 Token。英文约 1 单词 ≈ 1.3 Token。"},{"id":"ch1-1.3-q1","chapter":"ch1","section":"1.3","type":"single","difficulty":1,"question":"Few-shot Prompting 是指什么？","options":[{"key":"A","text":"不给示例直接让模型回答"},{"key":"B","text":"在 Prompt 中给出几个示例引导输出","correct":true},{"key":"C","text":"使用很少的 Token"},{"key":"D","text":"只问很少的问题"}],"explanation":"Few-shot 是在 Prompt 中给出 2-5 个示例，引导模型理解期望的输出格式和风格。Zero-shot 则是不给示例。"},{"id":"ch1-1.3-q2","chapter":"ch1","section":"1.3","type":"single","difficulty":2,"question":"Chain-of-Thought（CoT）的主要作用是？","options":[{"key":"A","text":"减少 Token 消耗"},{"key":"B","text":"提升推理任务的准确率","correct":true},{"key":"C","text":"加快响应速度"},{"key":"D","text":"降低 API 成本"}],"explanation":"CoT 让模型一步步思考，能显著提升数学推理、逻辑推理等复杂任务的准确率。"},{"id":"ch1-1.3-q3","chapter":"ch1","section":"1.3","type":"multiple","difficulty":2,"question":"以下哪些是 Prompt Engineering 的核心原则？（多选）","options":[{"key":"A","text":"清晰（Clear）- 指令明确无歧义","correct":true},{"key":"B","text":"具体（Specific）- 给出充分上下文","correct":true},{"key":"C","text":"结构化（Structured）- 用格式组织","correct":true},{"key":"D","text":"越长越好"}],"explanation":"三大核心原则是清晰、具体、结构化。Prompt 不是越长越好，过度约束反而让模型难以遵守。"},{"id":"ch1-1.4-q1","chapter":"ch1","section":"1.4","type":"single","difficulty":1,"question":"什么是 Hallucination（幻觉）？","options":[{"key":"A","text":"模型生成的图像看起来不真实"},{"key":"B","text":"模型生成看似合理但不正确的内容","correct":true},{"key":"C","text":"模型运行速度太慢"},{"key":"D","text":"模型无法理解中文"}],"explanation":"幻觉是指 LLM 生成看似合理但实际上不正确、不存在或误导性的内容。这是 Agent 开发中最危险的问题之一。"},{"id":"ch1-1.4-q2","chapter":"ch1","section":"1.4","type":"single","difficulty":2,"question":"以下哪种方法最能有效缓解幻觉问题？","options":[{"key":"A","text":"使用更高的 Temperature"},{"key":"B","text":"增加 max_tokens"},{"key":"C","text":"使用 RAG 检索真实信息","correct":true},{"key":"D","text":"使用更短的 Prompt"}],"explanation":"RAG（检索增强生成）通过检索真实信息作为上下文，能有效减少幻觉。低 Temperature 也有帮助，但 RAG 是最根本的解决方案。"},{"id":"ch1-1.4-q3","chapter":"ch1","section":"1.4","type":"fill","difficulty":2,"question":"LLM 的知识有截止日期，解决知识过时问题的技术叫 ___（缩写）。","answer":"RAG","acceptAnswers":["RAG","rag","检索增强生成"],"explanation":"RAG（Retrieval-Augmented Generation，检索增强生成）通过检索外部知识库来弥补 LLM 知识截止日期的限制。"},{"id":"ch1-1.5-q1","chapter":"ch1","section":"1.5","type":"single","difficulty":2,"question":"ReAct 范式是哪两个能力的结合？","options":[{"key":"A","text":"Reading + Acting"},{"key":"B","text":"Reasoning + Acting","correct":true},{"key":"C","text":"Real-time + Action"},{"key":"D","text":"Recall + Adapt"}],"explanation":"ReAct = Reasoning（推理）+ Acting（行动），核心循环是 Thought → Action → Observation。"},{"id":"ch1-1.5-q2","chapter":"ch1","section":"1.5","type":"single","difficulty":2,"question":"Agent 与传统软件的最本质区别是什么？","options":[{"key":"A","text":"Agent 使用 Python，传统软件使用 Java"},{"key":"B","text":"Agent 是概率性的，传统软件是确定性的","correct":true},{"key":"C","text":"Agent 运行在云端，传统软件运行在本地"},{"key":"D","text":"Agent 比传统软件更快"}],"explanation":"传统软件是确定性的（相同输入永远相同输出），而 Agent 是概率性的（LLM 推理引入不确定性）。"},{"id":"ch1-1.6-q1","chapter":"ch1","section":"1.6","type":"single","difficulty":1,"question":"本学习路线共有几章？","options":[{"key":"A","text":"4 章"},{"key":"B","text":"5 章"},{"key":"C","text":"6 章","correct":true},{"key":"D","text":"7 章"}],"explanation":"本学习路线共 6 章：基础概念入门 → 核心原理深入 → 框架与工具实战 → 多Agent系统设计 → 行业应用与最佳实践 → 前沿趋势展望。"},{"id":"ch1-1.6-q2","chapter":"ch1","section":"1.6","type":"single","difficulty":1,"question":"完成第 2 章后应达到哪个里程碑？","options":[{"key":"A","text":"M1 概念掌握"},{"key":"B","text":"M2 原理理解","correct":true},{"key":"C","text":"M3 框架实战"},{"key":"D","text":"M4 多Agent设计"}],"explanation":"第 2 章对应 M2 原理理解里程碑——能手写 Agent Loop，理解 RAG。"},{"id":"ch2-2.1-q1","chapter":"ch2","section":"2.1","type":"single","difficulty":2,"question":"Agent 的三层架构是指什么？","options":[{"key":"A","text":"前端层 + 后端层 + 数据层"},{"key":"B","text":"决策层 + 工具层 + 记忆层","correct":true},{"key":"C","text":"输入层 + 处理层 + 输出层"},{"key":"D","text":"模型层 + 训练层 + 推理层"}],"explanation":"Agent 三层架构：决策层（LLM 负责推理决策）+ 工具层（API/函数调用）+ 记忆层（上下文管理）。"},{"id":"ch2-2.1-q2","chapter":"ch2","section":"2.1","type":"single","difficulty":2,"question":"Agent Loop 的正确执行流程是什么？","options":[{"key":"A","text":"输入 → 输出"},{"key":"B","text":"输入 → 思考 → 工具调用 → 观察 → 再思考 → 输出","correct":true},{"key":"C","text":"输入 → 训练 → 推理 → 输出"},{"key":"D","text":"输入 → 缓存 → 输出"}],"explanation":"Agent Loop 流程：输入 → 思考 → 工具调用 → 观察结果 → 再思考（循环）→ 最终输出。这个循环是 Agent 自主性的体现。"},{"id":"ch2-2.1-q3","chapter":"ch2","section":"2.1","type":"fill","difficulty":2,"question":"防止 Agent 无限循环的常见机制是设置 ___ 参数。","answer":"max_steps","acceptAnswers":["max_steps","maxsteps","max iteration","max_iterations"],"explanation":"max_steps 参数限制 Agent 的最大循环次数，防止 Agent 陷入无限循环导致 Token 爆炸。"},{"id":"ch2-2.2-q1","chapter":"ch2","section":"2.2","type":"single","difficulty":2,"question":"ReAct 范式的核心循环是？","options":[{"key":"A","text":"思考 → 输出"},{"key":"B","text":"思考 → 行动 → 观察","correct":true},{"key":"C","text":"输入 → 输出"},{"key":"D","text":"规划 → 执行"}],"explanation":"ReAct = Reasoning + Acting，核心循环是 Thought → Action → Observation，模型在每一步先思考再行动，然后观察结果。"},{"id":"ch2-2.2-q2","chapter":"ch2","section":"2.2","type":"single","difficulty":3,"question":"ReAct 相比纯 CoT 的主要优势是什么？","options":[{"key":"A","text":"速度更快"},{"key":"B","text":"可以调用外部工具获取实时信息","correct":true},{"key":"C","text":"Token 消耗更少"},{"key":"D","text":"不需要 LLM"}],"explanation":"纯 CoT 只能基于模型内部知识推理，而 ReAct 可以调用外部工具（搜索、计算、API）获取实时信息，能力大幅扩展。"},{"id":"ch2-2.2-q3","chapter":"ch2","section":"2.2","type":"multiple","difficulty":3,"question":"ReAct 范式的局限性包括哪些？（多选）","options":[{"key":"A","text":"容易陷入循环，需要 max_steps 保护","correct":true},{"key":"B","text":"每一步都调用 LLM，Token 消耗大","correct":true},{"key":"C","text":"不能调用外部工具"},{"key":"D","text":"对简单任务可能过度设计","correct":true}],"explanation":"ReAct 的局限：容易循环失控、Token 消耗大、对简单任务过度设计。它不能调用外部工具是错误的——调用工具正是 ReAct 的核心能力。"},{"id":"ch2-2.3-q1","chapter":"ch2","section":"2.3","type":"single","difficulty":3,"question":"Plan-Execute 范式与 ReAct 的主要区别是什么？","options":[{"key":"A","text":"Plan-Execute 先规划全部步骤再执行，ReAct 逐步决策","correct":true},{"key":"B","text":"Plan-Execute 速度更快"},{"key":"C","text":"ReAct 不能调用工具"},{"key":"D","text":"Plan-Execute 不需要 LLM"}],"explanation":"Plan-Execute 先由 Planner Agent 制定完整计划，再由 Executor 逐步执行。ReAct 则是每一步都重新决策。Plan-Execute 适合复杂任务，ReAct 适合动态任务。"},{"id":"ch2-2.3-q2","chapter":"ch2","section":"2.3","type":"single","difficulty":3,"question":"Reflexion 机制的核心思想是什么？","options":[{"key":"A","text":"反射式快速响应"},{"key":"B","text":"从失败中反思并改进","correct":true},{"key":"C","text":"镜像复制行为"},{"key":"D","text":"减少 LLM 调用次数"}],"explanation":"Reflexion 是让 Agent 从失败的尝试中反思，总结经验教训，然后在下一次尝试中改进。这是一种自我提升机制。"},{"id":"ch2-2.4-q1","chapter":"ch2","section":"2.4","type":"single","difficulty":2,"question":"Function Calling 中，工具参数使用什么格式描述？","options":[{"key":"A","text":"XML"},{"key":"B","text":"JSON Schema","correct":true},{"key":"C","text":"YAML"},{"key":"D","text":"Protobuf"}],"explanation":"OpenAI Function Calling 使用 JSON Schema 描述工具的参数类型、必填字段等，让 LLM 理解如何调用工具。"},{"id":"ch2-2.4-q2","chapter":"ch2","section":"2.4","type":"single","difficulty":3,"question":"tool_choice 参数设为 'auto' 意味着什么？","options":[{"key":"A","text":"不调用任何工具"},{"key":"B","text":"让 LLM 自主决定是否调用工具","correct":true},{"key":"C","text":"必须调用所有工具"},{"key":"D","text":"随机选择工具"}],"explanation":"tool_choice='auto' 让 LLM 根据用户输入自主决定是否调用工具以及调用哪个工具。设为 'required' 则强制调用。"},{"id":"ch2-2.4-q3","chapter":"ch2","section":"2.4","type":"multiple","difficulty":3,"question":"以下哪些是 Function Calling 的最佳实践？（多选）","options":[{"key":"A","text":"工具描述清晰具体","correct":true},{"key":"B","text":"参数尽量复杂以体现能力"},{"key":"C","text":"使用 Pydantic 自动生成 Schema","correct":true},{"key":"D","text":"为失败调用设计降级方案","correct":true}],"explanation":"最佳实践：描述清晰、参数最小化（不是复杂化）、用 Pydantic 生成 Schema、设计错误处理。参数应尽量简单。"},{"id":"ch2-2.5-q1","chapter":"ch2","section":"2.5","type":"single","difficulty":3,"question":"Agent Loop 中消息列表的作用是什么？","options":[{"key":"A","text":"仅用于记录日志"},{"key":"B","text":"作为状态管理，传递上下文给 LLM","correct":true},{"key":"C","text":"用于性能监控"},{"key":"D","text":"用于错误追踪"}],"explanation":"消息列表是 Agent 的状态管理核心——包含 system prompt、用户输入、LLM 回复、工具调用和工具返回，每次都完整传给 LLM 作为上下文。"},{"id":"ch2-2.5-q2","chapter":"ch2","section":"2.5","type":"single","difficulty":3,"question":"Agent 循环失控的最常见原因是什么？","options":[{"key":"A","text":"网络延迟"},{"key":"B","text":"工具持续返回错误，Agent 不断重试","correct":true},{"key":"C","text":"用户输入太短"},{"key":"D","text":"模型版本太旧"}],"explanation":"循环失控常因工具返回错误或不可用，Agent 不断尝试不同的工具调用但没有 max_steps 保护，导致 Token 爆炸。"},{"id":"ch2-2.6-q1","chapter":"ch2","section":"2.6","type":"single","difficulty":2,"question":"Agent 的短期记忆通常指什么？","options":[{"key":"A","text":"向量数据库中的嵌入"},{"key":"B","text":"当前对话的消息历史","correct":true},{"key":"C","text":"用户配置文件"},{"key":"D","text":"系统日志"}],"explanation":"短期记忆是当前对话的消息历史（messages 列表），长期记忆是存储在向量数据库中的历史信息。"},{"id":"ch2-2.6-q2","chapter":"ch2","section":"2.6","type":"single","difficulty":3,"question":"滑动窗口记忆策略的核心思想是什么？","options":[{"key":"A","text":"删除所有旧消息"},{"key":"B","text":"保留最近的 N 条消息，超出部分丢弃或摘要","correct":true},{"key":"C","text":"将所有消息存入数据库"},{"key":"D","text":"只保留第一条消息"}],"explanation":"滑动窗口策略保留最近 N 条消息在上下文中，超出窗口的旧消息要么丢弃，要么用摘要压缩后保留，以控制 Token 消耗。"},{"id":"ch2-2.6-q3","chapter":"ch2","section":"2.6","type":"fill","difficulty":3,"question":"当对话历史超出 Context Window 时，将旧消息压缩为摘要的技术称为 ___。","answer":"摘要压缩","acceptAnswers":["摘要压缩","摘要","summarization","摘要化","压缩"],"explanation":"摘要压缩是将旧消息用 LLM 总结为简短摘要，减少 Token 消耗的同时保留关键信息。"},{"id":"ch2-2.7-q1","chapter":"ch2","section":"2.7","type":"single","difficulty":2,"question":"强制 LLM 输出 JSON 格式的 OpenAI 参数是什么？","options":[{"key":"A","text":"temperature=0"},{"key":"B","text":"response_format={'type': 'json_object'}","correct":true},{"key":"C","text":"max_tokens=4096"},{"key":"D","text":"stream=True"}],"explanation":"response_format={'type': 'json_object'} 强制模型输出合法 JSON。也可用 tool_choice 强制调用特定工具来获得结构化输出。"},{"id":"ch2-2.7-q2","chapter":"ch2","section":"2.7","type":"single","difficulty":3,"question":"Pydantic 在结构化输出中的主要作用是什么？","options":[{"key":"A","text":"加速 LLM 推理"},{"key":"B","text":"校验 LLM 输出是否符合预期格式","correct":true},{"key":"C","text":"减少 Token 消耗"},{"key":"D","text":"替代 LLM"}],"explanation":"Pydantic 定义数据模型，自动校验 LLM 输出的字段类型、必填性、值范围，校验失败可触发重试。"},{"id":"ch2-2.8-q1","chapter":"ch2","section":"2.8","type":"single","difficulty":2,"question":"RAG 的全称是什么？","options":[{"key":"A","text":"Random Access Generator"},{"key":"B","text":"Retrieval-Augmented Generation","correct":true},{"key":"C","text":"Rapid Application Generation"},{"key":"D","text":"Recursive Algorithm Graph"}],"explanation":"RAG = Retrieval-Augmented Generation（检索增强生成），通过检索外部知识来增强 LLM 的生成质量。"},{"id":"ch2-2.8-q2","chapter":"ch2","section":"2.8","type":"single","difficulty":3,"question":"RAG 全链路中，将文本转为向量的过程称为？","options":[{"key":"A","text":"Chunking"},{"key":"B","text":"Embedding","correct":true},{"key":"C","text":"Reranking"},{"key":"D","text":"Indexing"}],"explanation":"Embedding（嵌入）是将文本映射为高维向量，使语义相近的文本在向量空间中距离也近，是向量检索的基础。"},{"id":"ch2-2.8-q3","chapter":"ch2","section":"2.8","type":"multiple","difficulty":3,"question":"以下哪些是常见的 RAG 分块（Chunking）策略？（多选）","options":[{"key":"A","text":"固定大小分块","correct":true},{"key":"B","text":"语义切分（按句子/段落）","correct":true},{"key":"C","text":"递归切分","correct":true},{"key":"D","text":"随机切分"}],"explanation":"常见分块策略：固定大小（按字符数）、语义切分（按句子/段落边界）、递归切分（多级分割）。随机切分会破坏语义完整性。"},{"id":"ch2-2.9-q1","chapter":"ch2","section":"2.9","type":"single","difficulty":3,"question":"Prompt Injection（提示注入）攻击是指什么？","options":[{"key":"A","text":"注入恶意代码到服务器"},{"key":"B","text":"通过用户输入覆盖 System Prompt 指令","correct":true},{"key":"C","text":"攻击 API 接口"},{"key":"D","text":"破解模型权重"}],"explanation":"Prompt Injection 是攻击者通过用户输入注入恶意指令，试图覆盖或绕过 System Prompt 的安全限制，是 LLM 应用的主要安全威胁。"},{"id":"ch2-2.9-q2","chapter":"ch2","section":"2.9","type":"single","difficulty":3,"question":"Guardrail（安全护栏）的主要作用是什么？","options":[{"key":"A","text":"提高模型推理速度"},{"key":"B","text":"限制 Agent 行为在安全范围内","correct":true},{"key":"C","text":"减少 Token 消耗"},{"key":"D","text":"美化输出格式"}],"explanation":"Guardrail 是安全防护机制，确保 Agent 不会执行危险操作、不输出有害内容、不超出能力边界。"},{"id":"ch2-2.10-q1","chapter":"ch2","section":"2.10","type":"single","difficulty":2,"question":"Agent 评估的四个主要维度是什么？","options":[{"key":"A","text":"速度、内存、CPU、磁盘"},{"key":"B","text":"准确性、效率、成本、鲁棒性","correct":true},{"key":"C","text":"前端、后端、数据库、网络"},{"key":"D","text":"训练、验证、测试、部署"}],"explanation":"Agent 评估四维度：准确性（任务完成质量）、效率（步骤/时间）、成本（Token消耗）、鲁棒性（异常处理能力）。"},{"id":"ch2-2.10-q2","chapter":"ch2","section":"2.10","type":"single","difficulty":3,"question":"以下哪个是专门用于 RAG 评估的框架？","options":[{"key":"A","text":"Pytest"},{"key":"B","text":"RAGAS","correct":true},{"key":"C","text":"Selenium"},{"key":"D","text":"Jest"}],"explanation":"RAGAS（RAG Assessment）是专门评估 RAG 系统质量的框架，评估检索准确率、生成质量、忠实度等指标。"},{"id":"ch3-3.1-q1","chapter":"ch3","section":"3.1","type":"single","difficulty":2,"question":"以下哪个框架最适合构建有状态的多步骤 Agent 工作流？","options":[{"key":"A","text":"LangChain"},{"key":"B","text":"LangGraph","correct":true},{"key":"C","text":"OpenAI Agents SDK"},{"key":"D","text":"DSPy"}],"explanation":"LangGraph 专为有状态图编排设计，支持条件路由、循环控制、检查点恢复，最适合复杂多步骤工作流。"},{"id":"ch3-3.1-q2","chapter":"ch3","section":"3.1","type":"single","difficulty":2,"question":"以下哪个框架是 Anthropic 推出的工具标准化协议？","options":[{"key":"A","text":"MCP（Model Context Protocol）","correct":true},{"key":"B","text":"LangChain"},{"key":"C","text":"CrewAI"},{"key":"D","text":"AutoGen"}],"explanation":"MCP（Model Context Protocol）是 Anthropic 推出的工具调用标准协议，实现 Agent 与工具的解耦。"},{"id":"ch3-3.2-q1","chapter":"ch3","section":"3.2","type":"single","difficulty":2,"question":"LangChain 的 LCEL 是指什么？","options":[{"key":"A","text":"一种编程语言"},{"key":"B","text":"LangChain Expression Language，管道语法","correct":true},{"key":"C","text":"一种数据库"},{"key":"D","text":"一种模型架构"}],"explanation":"LCEL（LangChain Expression Language）是 LangChain 的管道语法，用 | 操作符串联组件，如 prompt | model | parser。"},{"id":"ch3-3.2-q2","chapter":"ch3","section":"3.2","type":"single","difficulty":2,"question":"想让模型返回一个字段类型可校验的对象，而不是自己写正则解析 JSON 字符串，应该用？","options":[{"key":"A","text":"StrOutputParser()"},{"key":"B","text":"llm.with_structured_output(PydanticModel)","correct":true},{"key":"C","text":"在提示词里写「请返回 JSON」"},{"key":"D","text":"json.loads(response.content)"}],"explanation":"with_structured_output 底层走 Function Calling，由 SDK 保证返回已通过 Pydantic 校验的对象。仅在提示词里要求返回 JSON，模型多输出一个 markdown 围栏就会解析失败。"},{"id":"ch3-3.2-q3","chapter":"ch3","section":"3.2","type":"single","difficulty":3,"question":"使用 RunnableWithMessageHistory 时，config 里的 session_id 起什么作用？","options":[{"key":"A","text":"标识调用哪个模型"},{"key":"B","text":"区分不同会话的历史，实现多用户互不串台","correct":true},{"key":"C","text":"控制历史保留的轮数上限"},{"key":"D","text":"指定历史存储在内存还是 Redis"}],"explanation":"session_id 是历史仓库的 key。换一个 session_id 就是一段全新的对话，这正是多用户隔离的实现方式。保留轮数需要另外做裁剪（如 trim_messages）。"},{"id":"ch3-3.2-q4","chapter":"ch3","section":"3.2","type":"single","difficulty":3,"question":"用 create_tool_calling_agent 构建 Agent 时，prompt 中为什么必须包含 agent_scratchpad 插槽？","options":[{"key":"A","text":"用来存放系统提示词"},{"key":"B","text":"用来存放用户的历史对话"},{"key":"C","text":"用来存放已调用工具及其返回结果，模型据此判断下一步","correct":true},{"key":"D","text":"用来限制工具调用次数"}],"explanation":"agent_scratchpad 承载「已经调了哪些工具、各自返回了什么」的中间步骤。缺了它，模型每轮都像第一次执行，会陷入重复调用同一工具的死循环。"},{"id":"ch3-3.2-q5","chapter":"ch3","section":"3.2","type":"single","difficulty":3,"question":"RAG 应用出现「答非所问」时，正确的排查顺序是？","options":[{"key":"A","text":"先换更强的模型，再调提示词，最后看检索"},{"key":"B","text":"先打印检索回来的片段，再看提示词拼接，最后才怀疑模型","correct":true},{"key":"C","text":"先加大 chunk_size，再加大 k，最后换向量库"},{"key":"D","text":"先看模型温度参数，再看 Embedding 维度"}],"explanation":"绝大多数「AI 胡说八道」的根因在检索阶段就没召回正确片段。用 retriever.invoke(问题) 打印结果是成本最低、信息量最大的第一步；模型是最后才该被怀疑的环节。"},{"id":"ch3-3.3-q1","chapter":"ch3","section":"3.3","type":"single","difficulty":3,"question":"LangGraph 中实现条件路由的 API 是？","options":[{"key":"A","text":"add_edge()"},{"key":"B","text":"add_conditional_edges()","correct":true},{"key":"C","text":"add_node()"},{"key":"D","text":"add_route()"}],"explanation":"add_conditional_edges() 根据状态动态决定下一个节点，是 LangGraph 实现分支逻辑的核心 API。"},{"id":"ch3-3.6-q1","chapter":"ch3","section":"3.6","type":"single","difficulty":3,"question":"MCP 协议基于哪种通信机制？","options":[{"key":"A","text":"HTTP REST"},{"key":"B","text":"JSON-RPC 2.0","correct":true},{"key":"C","text":"WebSocket"},{"key":"D","text":"gRPC"}],"explanation":"MCP 基于 JSON-RPC 2.0 协议进行通信，支持 stdio 和 SSE 两种传输方式。"},{"id":"ch3-3.8-q1","chapter":"ch3","section":"3.8","type":"single","difficulty":3,"question":"传统软件系统（非 Agent）可观测性的三大支柱是什么？","options":[{"key":"A","text":"前端、后端、数据库"},{"key":"B","text":"Logs、Metrics、Traces","correct":true},{"key":"C","text":"CPU、内存、磁盘"},{"key":"D","text":"输入、处理、输出"}],"explanation":"传统可观测性三大支柱：Logs（日志）、Metrics（指标）、Traces（链路追踪）。在 LLM Agent 场景里，Traces / Metrics 之外常以 Evals（评估）替代 Logs 成为第三支柱，因为 Agent 输出是开放文本，靠日志很难判断\"对不对\"。"},{"id":"ch4-4.1-q1","chapter":"ch4","section":"4.1","type":"single","difficulty":3,"question":"多 Agent 层级式架构的核心模式是什么？","options":[{"key":"A","text":"所有 Agent 平等协作"},{"key":"B","text":"Manager-Worker 模式，管理者分配任务","correct":true},{"key":"C","text":"Agent 之间随机通信"},{"key":"D","text":"只有一个 Agent"}],"explanation":"层级式架构采用 Manager-Worker 模式：Manager Agent 负责任务分解和分配，Worker Agent 负责具体执行，结果汇总给 Manager。"},{"id":"ch4-4.1-q2","chapter":"ch4","section":"4.1","type":"single","difficulty":3,"question":"黑板模式（Blackboard）的核心特征是什么？","options":[{"key":"A","text":"Agent 之间直接通信"},{"key":"B","text":"通过共享状态空间通信","correct":true},{"key":"C","text":"只有一个 Agent 工作"},{"key":"D","text":"使用数据库存储"}],"explanation":"黑板模式中所有 Agent 共享一个状态空间（黑板），Agent 向黑板写入结果，从黑板读取需要的信息，实现松耦合协作。"},{"id":"ch4-4.4-q1","chapter":"ch4","section":"4.4","type":"single","difficulty":4,"question":"DAG 编排中 DAG 的全称是？","options":[{"key":"A","text":"Data Access Graph"},{"key":"B","text":"Directed Acyclic Graph（有向无环图）","correct":true},{"key":"C","text":"Dynamic Agent Group"},{"key":"D","text":"Distributed Architecture Grid"}],"explanation":"DAG = Directed Acyclic Graph（有向无环图），任务之间有明确依赖关系，无循环，是多 Agent 任务编排的基础模型。"},{"id":"ch4-4.7-q1","chapter":"ch4","section":"4.7","type":"single","difficulty":3,"question":"Human-in-the-Loop（HITL）的主要价值是什么？","options":[{"key":"A","text":"提高系统速度"},{"key":"B","text":"在关键决策点引入人工判断，提高安全性","correct":true},{"key":"C","text":"减少开发工作量"},{"key":"D","text":"替代 LLM"}],"explanation":"HITL 在关键决策点（如金融交易、敏感操作）暂停 Agent 执行，等待人工审批后再继续，平衡自动化效率与安全可控。"},{"id":"ch5-5.1-q1","chapter":"ch5","section":"5.1","type":"single","difficulty":2,"question":"智能客服 Agent 中，意图识别路由的主要作用是什么？","options":[{"key":"A","text":"加速响应"},{"key":"B","text":"根据用户意图分配到不同处理流程","correct":true},{"key":"C","text":"减少 Token"},{"key":"D","text":"美化界面"}],"explanation":"意图识别路由根据用户输入判断意图类型（咨询/投诉/查询），将对话分配到最合适的处理 Agent 或流程。"},{"id":"ch5-5.3-q1","chapter":"ch5","section":"5.3","type":"single","difficulty":3,"question":"NL2SQL 是指什么？","options":[{"key":"A","text":"NoSQL 数据库"},{"key":"B","text":"自然语言转 SQL 查询","correct":true},{"key":"C","text":"SQL 性能优化"},{"key":"D","text":"SQL 注入防护"}],"explanation":"NL2SQL（Natural Language to SQL）让用户用自然语言提问，Agent 自动生成 SQL 查询数据库并返回结果，是数据分析 Agent 的核心技术。"},{"id":"ch5-5.8-q1","chapter":"ch5","section":"5.8","type":"single","difficulty":3,"question":"生产级 Agent 服务常用的 Python Web 框架是？","options":[{"key":"A","text":"Django"},{"key":"B","text":"Flask"},{"key":"C","text":"FastAPI","correct":true},{"key":"D","text":"Bottle"}],"explanation":"FastAPI 原生支持异步、自动生成 API 文档、性能优秀，是 Agent 服务化的首选框架。"},{"id":"ch5-5.9-q1","chapter":"ch5","section":"5.9","type":"single","difficulty":3,"question":"工具权限最小化原则是指什么？","options":[{"key":"A","text":"不给 Agent 任何工具"},{"key":"B","text":"只授予完成任务所需的最少工具权限","correct":true},{"key":"C","text":"只使用一个工具"},{"key":"D","text":"工具权限随机分配"}],"explanation":"最小化原则：Agent 只拥有完成任务所需的最少工具和权限，降低被 Prompt Injection 攻击后的危害范围。"},{"id":"ch5-5.10-q1","chapter":"ch5","section":"5.10","type":"single","difficulty":2,"question":"Agent 循环失控导致的最直接后果是什么？","options":[{"key":"A","text":"服务器崩溃"},{"key":"B","text":"Token 消耗爆炸，API 费用飙升","correct":true},{"key":"C","text":"用户被锁定"},{"key":"D","text":"数据丢失"}],"explanation":"Agent 循环失控会不断调用 LLM API，导致 Token 消耗指数级增长，API 费用飙升。必须用 max_steps 和费用上限保护。"},{"id":"ch6-6.1-q1","chapter":"ch6","section":"6.1","type":"single","difficulty":3,"question":"Agent OS 的愿景是什么？","options":[{"key":"A","text":"替代传统操作系统"},{"key":"B","text":"为 Agent 提供标准化运行环境与互操作能力","correct":true},{"key":"C","text":"加速模型训练"},{"key":"D","text":"替代 LLM"}],"explanation":"Agent OS 旨在为 AI Agent 提供标准化的运行环境、资源管理和互操作能力，类似传统 OS 对应用程序的作用。"},{"id":"ch6-6.3-q1","chapter":"ch6","section":"6.3","type":"single","difficulty":3,"question":"AGI 的全称是什么？","options":[{"key":"A","text":"Automated General Interface"},{"key":"B","text":"Artificial General Intelligence","correct":true},{"key":"C","text":"Agent Generation Interface"},{"key":"D","text":"Advanced GPU Integration"}],"explanation":"AGI = Artificial General Intelligence（通用人工智能），指能像人类一样在各种任务中表现出智能的 AI 系统。"},{"id":"ch6-6.5-q1","chapter":"ch6","section":"6.5","type":"single","difficulty":3,"question":"RLHF 是什么技术？","options":[{"key":"A","text":"一种数据库"},{"key":"B","text":"基于人类反馈的强化学习","correct":true},{"key":"C","text":"一种编程语言"},{"key":"D","text":"一种网络协议"}],"explanation":"RLHF = Reinforcement Learning from Human Feedback，通过人类反馈对模型进行强化学习，是 AI 对齐（Alignment）的核心技术。"},{"id":"ch3-3.4-q1","chapter":"ch3","section":"3.4","type":"single","difficulty":2,"question":"OpenAI Agents SDK 中负责驱动 Agent 运行、返回最终结果的核心执行引擎是？","options":[{"key":"A","text":"Agent"},{"key":"B","text":"Runner","correct":true},{"key":"C","text":"Handoff"},{"key":"D","text":"function_tool"}],"explanation":"Runner（如 Runner.run_sync）是执行引擎，负责调度 Agent、自动处理工具调用循环并返回最终结果；Agent 定义角色，Handoff 用于 Agent 间转接。"},{"id":"ch3-3.5-q1","chapter":"ch3","section":"3.5","type":"single","difficulty":3,"question":"在 LlamaIndex 中，负责把文档切分、向量化并构建成可检索结构的核心抽象是？","options":[{"key":"A","text":"Agent"},{"key":"B","text":"VectorStoreIndex","correct":true},{"key":"C","text":"Retriever"},{"key":"D","text":"Node Parser"}],"explanation":"VectorStoreIndex.from_documents 内部完成切分、向量化与索引构建，是 LlamaIndex RAG 最常用的入口；Retriever 负责检索，Node Parser 只负责切分。"},{"id":"ch3-3.7-q1","chapter":"ch3","section":"3.7","type":"single","difficulty":2,"question":"下列哪种场景最适合优先选择低代码平台（如 Dify）而非纯代码开发？","options":[{"key":"A","text":"需要深度定制的高性能系统"},{"key":"B","text":"快速验证 POC 且团队编程能力有限","correct":true},{"key":"C","text":"长期维护的大型分布式项目"},{"key":"D","text":"对延迟极度敏感的实时推理"}],"explanation":"低代码平台适合快速验证、标准应用与编程能力有限的团队；复杂逻辑、高性能、深度定制仍需代码开发。"},{"id":"ch3-3.9-q1","chapter":"ch3","section":"3.9","type":"single","difficulty":3,"question":"对 Agent 生成的代码，生产环境最安全的执行方式是？","options":[{"key":"A","text":"直接在宿主服务器运行"},{"key":"B","text":"在沙箱（Docker/E2B）中隔离执行","correct":true},{"key":"C","text":"仅在本机浏览器运行"},{"key":"D","text":"不需要执行，只返回代码"}],"explanation":"Agent 生成的代码不可信，必须在沙箱中隔离执行：限制网络、内存、CPU，容器即毁，防止删文件、泄露数据或逃逸。"},{"id":"ch4-4.2-q1","chapter":"ch4","section":"4.2","type":"single","difficulty":3,"question":"在 CrewAI 中，用哪个对象把多个角色（Agent）与任务（Task）编排成一条协作流水线？","options":[{"key":"A","text":"Agent"},{"key":"B","text":"Task"},{"key":"C","text":"Crew","correct":true},{"key":"D","text":"Tool"}],"explanation":"Crew 负责把 Agents 与 Tasks 按依赖关系组装并启动协作；Agent 定义角色，Task 定义任务。"},{"id":"ch4-4.3-q1","chapter":"ch4","section":"4.3","type":"single","difficulty":3,"question":"多 Agent 之间通过共享状态对象（TypedDict）传递中间结果的方式，最适合哪种流程？","options":[{"key":"A","text":"任意复杂对话"},{"key":"B","text":"线性流水线","correct":true},{"key":"C","text":"群聊辩论"},{"key":"D","text":"事件订阅"}],"explanation":"共享状态适合线性、依赖清晰的流水线；复杂交互或群聊更适合消息传递模式。"},{"id":"ch4-4.5-q1","chapter":"ch4","section":"4.5","type":"single","difficulty":3,"question":"多个 Agent 给出不同的代码审查意见且相互冲突时，最稳妥的聚合策略是？","options":[{"key":"A","text":"随机选一个"},{"key":"B","text":"取最严格（Critic）建议","correct":true},{"key":"C","text":"按多数票"},{"key":"D","text":"忽略冲突"}],"explanation":"质量敏感的代码审查应以最严格建议兜底，避免中低风险项被多数票掩盖。"},{"id":"ch4-4.6-q1","chapter":"ch4","section":"4.6","type":"single","difficulty":4,"question":"LangGraph 中支持长任务“断点恢复、中断后继续”的核心机制是？","options":[{"key":"A","text":"Handoff"},{"key":"B","text":"Checkpoint / Persistence","correct":true},{"key":"C","text":"interrupt"},{"key":"D","text":"Mermaid"}],"explanation":"Checkpoint（如 MemorySaver/PostgresSaver）在每步后持久化状态，凭 thread_id 即可从断点恢复。"},{"id":"ch4-4.8-q1","chapter":"ch4","section":"4.8","type":"single","difficulty":3,"question":"当目标操作已有可用的 API 时，Agent 应优先选择哪种方式？","options":[{"key":"A","text":"Computer Use 截图操作 GUI"},{"key":"B","text":"纯 API 调用","correct":true},{"key":"C","text":"RPA 录屏回放"},{"key":"D","text":"Playwright 截图理解"}],"explanation":"能用 API 就不要用 GUI：API 最快最可靠、成本低；GUI 自动化慢且脆弱。"},{"id":"ch3-3.1-q3","chapter":"ch3","section":"3.1","type":"single","difficulty":2,"question":"团队要做一个 5 步的采购审批 Agent：第 3 步必须由主管点击确认才能继续，且任意一步失败后要能从失败处恢复。以下哪个框架最贴合这两个硬需求？","options":[{"key":"A","text":"LangChain，因为它生态最大、教程最多"},{"key":"B","text":"LangGraph，它的 checkpointer 支持断点续跑，`interrupt()` 支持挂起等待人工输入","correct":true},{"key":"C","text":"LlamaIndex，因为它的 Workflow 也能编排多步流程"},{"key":"D","text":"OpenAI Agents SDK，因为它最轻量、上手最快"}],"explanation":"题目给出的两个硬需求正是“状态持久化”和“HITL”两个维度。LangGraph 的 checkpointer 与 interrupt / Command 恢复机制是为此设计的一等公民能力。LangChain 缺少内建持久化与挂起；LlamaIndex 的强项在检索侧；OpenAI Agents SDK 抽象薄，审批与续跑都要自建。"},{"id":"ch3-3.1-q4","chapter":"ch3","section":"3.1","type":"single","difficulty":2,"question":"关于“要不要上框架”，下列哪种判断最符合工程实践？","options":[{"key":"A","text":"任何 Agent 项目第一天就应该选定框架，否则后面一定要重写"},{"key":"B","text":"永远不要用框架，自建才能完全掌控"},{"key":"C","text":"先用最裸的方式跑通一条端到端主链路，当出现断点续跑、人工审批、追踪定位这类需求时再引入框架","correct":true},{"key":"D","text":"按 GitHub star 数选，star 最多的框架适配性最好"}],"explanation":"过早抽象会让团队把时间耗在跟框架搏斗上；过晚抽象则会演变成自研一个更烂的框架。健康节奏是先跑通主链路，再用“是否需要状态持久化 / HITL / 可观测性”这些信号来决定引入时机。star 数反映的是传播度而不是适配度。"},{"id":"ch3-3.1-q5","chapter":"ch3","section":"3.1","type":"single","difficulty":3,"question":"某团队用低代码平台搭客服 Agent，初期很顺利。半年后画布长到 40 多个节点，出现了“改一个分支就莫名影响另一条链路、无法 code review、没人敢动”的情况。以下哪个是最合理的根因分析与止损方向？","options":[{"key":"A","text":"根因是平台性能不足，应该升级到更高配置的服务器"},{"key":"B","text":"根因是模型能力不够，应该把 gpt-4o-mini 换成更强的模型"},{"key":"C","text":"根因是把低代码当万能：画布规模超过阈值后 diff、单测、复用、review 全部失效；应设节点数红线，把复杂逻辑下沉为代码实现的 API，画布只做前端编排","correct":true},{"key":"D","text":"根因是选型时没选 star 数最多的平台，应该立刻整体迁移到 LangGraph 重写"}],"explanation":"这是典型的“低代码万能论”反模式。症状（无法 diff、无法单测、没人敢改）指向工程可维护性失效，而不是算力或模型能力问题。止损做法是设定复杂度红线并做分层：复杂逻辑用代码实现并暴露为 API，画布只保留编排。选项 D 的整体重写既昂贵，也没有解决“逻辑写在画布里”这个本质问题。"},{"id":"ch3-3.1-q6","chapter":"ch3","section":"3.1","type":"single","difficulty":3,"question":"“逃生舱”设计的核心原则是什么？","options":[{"key":"A","text":"同时接入两个框架并行运行，随时可以切换流量"},{"key":"B","text":"把领域逻辑写成不 import 任何框架的纯函数，框架只负责调用顺序，换框架时只重写最外层的壳","correct":true},{"key":"C","text":"只使用低代码平台，因为可视化配置天然与代码解耦"},{"key":"D","text":"把所有状态都存进框架自带的存储里，迁移时直接导出即可"}],"explanation":"逃生舱的目标不是“永不换框架”，而是“让换框架变得便宜”。做法是分层：领域层是纯函数、可单测、零框架依赖；编排壳负责适配具体框架。选项 A 成本翻倍；C 恰恰是绑定更深；D 把状态交给框架反而增加了迁移难度。"},{"id":"ch3-3.1-q7","chapter":"ch3","section":"3.1","type":"single","difficulty":2,"question":"用打分脚本对 RAG 问答场景排序后得到：LangChain 47 分、LlamaIndex 46 分、LangGraph 43 分。此时最恰当的做法是？","options":[{"key":"A","text":"直接选 LangChain，分数最高就是最优解"},{"key":"B","text":"1 分差距在主观打分的噪声范围内，应对前两名做 spike，用最难用例的实际表现来决定","correct":true},{"key":"C","text":"继续微调权重，直到某个框架明显领先为止"},{"key":"D","text":"三个都放弃，重新寻找一个能拿到 60 分以上的框架"}],"explanation":"打分表的权重是主观的、分数是有时效的，它的作用是收敛候选集和暴露团队分歧，而不是给出结论。47 比 46 的差距没有统计意义。选项 C 是典型的用调参凑结论（先射箭后画靶）；正确做法是转入 spike 验证。"},{"id":"ch3-3.3-q2","chapter":"ch3","section":"3.3","type":"single","difficulty":2,"question":"关于 `add_conditional_edges` 的路由函数，下列说法正确的是？","options":[{"key":"A","text":"它是一个普通节点，返回值会被合并进 State"},{"key":"B","text":"它只读状态并返回一个字符串，该字符串是目标节点名或 path_map 的键","correct":true},{"key":"C","text":"它必须返回布尔值，True 走第一条边、False 走第二条边"},{"key":"D","text":"它必须返回 END 或 START 之一"}],"explanation":"路由函数只负责「选路」，不参与状态更新：它接收 state，返回一个字符串作为下一站。省略 path_map 时该字符串必须直接是节点名；提供 path_map 时则是它的键。返回值不在可选集合内会在运行时报错。"},{"id":"ch3-3.3-q3","chapter":"ch3","section":"3.3","type":"single","difficulty":2,"question":"`config={\"configurable\": {\"thread_id\": \"u-001\"}}` 中 thread_id 的作用是什么？","options":[{"key":"A","text":"指定图执行使用的线程池大小，用于并发提速"},{"key":"B","text":"标识一条独立会话线：同一 thread_id 续接历史状态，不同 thread_id 互相隔离","correct":true},{"key":"C","text":"checkpoint 文件名，必须与 sqlite 文件同名"},{"key":"D","text":"只在 interrupt 场景需要，普通多轮对话可以省略"}],"explanation":"thread_id 是 checkpointer 的会话标识，与操作系统线程无关。同一个 thread_id 的多次 invoke 会自动从上次 checkpoint 续跑，不同 thread_id 的状态彼此不可见，因此它天然承担多用户/多会话隔离。"},{"id":"ch3-3.3-q4","chapter":"ch3","section":"3.3","type":"single","difficulty":3,"question":"某同学写了 `graph = builder.compile(interrupt_before=[\"execute_refund\"])`，第一次 invoke 后确实停住了，但接着执行 `graph.invoke(None, config)` 却报错、无法从断点恢复。最可能的原因是？","options":[{"key":"A","text":"compile 时没有传 checkpointer，断点现场没被持久化，自然无法恢复","correct":true},{"key":"B","text":"interrupt_before 只能配合 interrupt_after 一起使用"},{"key":"C","text":"恢复时必须传入完整的初始输入，不能传 None"},{"key":"D","text":"recursion_limit 默认值太小，需要调大到 50"}],"explanation":"断点能「停下再继续」的前提是状态被 checkpointer 保存。没有 checkpointer 时，图跑完这次调用现场就丢了，`invoke(None, config)` 拿不到任何可恢复的状态。正确写法是 `compile(checkpointer=cp, interrupt_before=[...])`，并且恢复时使用同一个 thread_id。"},{"id":"ch3-3.3-q5","chapter":"ch3","section":"3.3","type":"single","difficulty":3,"question":"State 里的 `messages` 字段被多个节点写入后总是互相覆盖、只剩最后一条，应该怎么改？","options":[{"key":"A","text":"在每个节点里手动 `state[\"messages\"].append(...)` 并返回整个 state"},{"key":"B","text":"把字段声明为 `Annotated[list[AnyMessage], add_messages]`，节点只返回新增消息","correct":true},{"key":"C","text":"把 State 从 TypedDict 换成 Pydantic BaseModel 即可自动累加"},{"key":"D","text":"改用 interrupt_after 让每个节点执行后立刻落盘"}],"explanation":"State 字段默认是覆盖语义，要累加必须声明 reducer。消息列表的标准写法是 `Annotated[list[AnyMessage], add_messages]`（通用列表可用 `operator.add`），此时节点只返回新增部分，框架负责合并；返回整个 state 反而会造成重复累加。"},{"id":"ch3-3.3-q6","chapter":"ch3","section":"3.3","type":"single","difficulty":2,"question":"下列哪种需求最应该用 LangGraph StateGraph 而不是纯 LCEL 链？","options":[{"key":"A","text":"把一段长文本批量改写成三种语气的营销文案"},{"key":"B","text":"固定「检索 → 拼 Prompt → 生成」三步的单轮 RAG 问答"},{"key":"C","text":"退款 Agent：自动核算金额，大额时暂停等人工审批，通过后继续打款并支持服务重启续跑","correct":true},{"key":"D","text":"调用一次模型做结构化信息抽取并解析成 JSON"}],"explanation":"A/B/D 都是一次跑完的直线流程，LCEL 更简洁。C 同时需要条件分支、执行中暂停（HITL）和跨进程恢复（checkpointer），这三项都是 LangGraph 的原生能力，用 LCEL 只能自己造轮子。"},{"id":"ch3-3.4-q2","chapter":"ch3","section":"3.4","type":"single","difficulty":2,"question":"相比 LangChain / LangGraph，OpenAI Agents SDK 最突出的特点是？","options":[{"key":"A","text":"提供完整的图状态机和 Checkpointer"},{"key":"B","text":"轻量、原语化，几行代码即可跑起 Agent","correct":true},{"key":"C","text":"内置持久化长期记忆数据库"},{"key":"D","text":"只支持单个 Agent，不支持多 Agent"}],"explanation":"Agents SDK 定位就是轻量原语运行时，核心抽象是 Agent/Handoff/Guardrail/Session/Tracing，不提供 LangGraph 那样的图状态机。"},{"id":"ch3-3.4-q3","chapter":"ch3","section":"3.4","type":"single","difficulty":2,"question":"Runner.run_sync(agent, input) 的返回值是什么类型，其中哪个字段是模型的最终答案？","options":[{"key":"A","text":"str，返回值是 final_output 字符串"},{"key":"B","text":"RunResult，final_output 是最终答案","correct":true},{"key":"C","text":"list，返回值是对话消息列表"},{"key":"D","text":"dict，键为 answer"}],"explanation":"Runner.run_sync 返回 RunResult 对象，final_output 是模型最终产出，to_input_list() 可回放完整对话轨迹。"},{"id":"ch3-3.4-q4","chapter":"ch3","section":"3.4","type":"single","difficulty":2,"question":"关于 @function_tool 与 handoff，下列说法正确的是？","options":[{"key":"A","text":"function_tool 需要手写 JSON schema，handoff 只能用于两个 Agent"},{"key":"B","text":"function_tool 自动从函数签名生成 schema；handoff 让主 Agent 把任务转交给子 Agent","correct":true},{"key":"C","text":"handoff 必须在异步环境下才能使用"},{"key":"D","text":"function_tool 只能装饰异步函数"}],"explanation":"function_tool 自动根据签名与文档字符串生成工具 schema；handoff 把子 Agent 放入主 Agent 的 handoffs 列表即可实现转交，同步异步都可用。"},{"id":"ch3-3.4-q5","chapter":"ch3","section":"3.4","type":"single","difficulty":3,"question":"InputGuardrail 的护栏函数返回 GuardrailFunctionOutput(tripwire_triggered=True) 时，会发生什么？","options":[{"key":"A","text":"主 Agent 正常继续运行，仅记录日志"},{"key":"B","text":"抛出 GuardrailTripwireTriggered，主流程被中断","correct":true},{"key":"C","text":"自动把输入替换为空字符串"},{"key":"D","text":"SDK 直接终止整个 Python 进程"}],"explanation":"tripwire 触发会抛出 GuardrailTripwireTriggered 异常，可用 try/except 捕获并做兜底处理，而不是让程序崩溃。"},{"id":"ch3-3.4-q6","chapter":"ch3","section":"3.4","type":"single","difficulty":3,"question":"排查题：你用多次 Runner.run_sync 调用同一个 Agent 想实现多轮对话，但 Agent 总忘记上一轮内容，最可能的原因是？","options":[{"key":"A","text":"需要在 Agent 上设置 memory=True 参数"},{"key":"B","text":"Agents SDK 不支持多轮，必须换 LangGraph"},{"key":"C","text":"SDK 不内置长期记忆，需把上一轮 result.to_input_list() 回灌到下一轮输入","correct":true},{"key":"D","text":"必须开启 Tracing 才能记住对话"}],"explanation":"Agents SDK 每次调用都是无状态的，没有内置长期记忆；正确做法是用 RunResult.to_input_list() 把历史拼接进下一轮输入来模拟记忆。"},{"id":"ch3-3.5-q2","chapter":"ch3","section":"3.5","type":"single","difficulty":2,"question":"在 LlamaIndex 中，`Document` 与 `Node` 的关系是？","options":[{"key":"A","text":"Node 是原始文档，Document 是切分后的片段"},{"key":"B","text":"Document 是一篇原始文档，Node 是切分后带 metadata 的片段，检索命中的是 Node","correct":true},{"key":"C","text":"两者完全等价，只是不同版本的命名差异"},{"key":"D","text":"Document 存文本，Node 只存向量，不含文本内容"}],"explanation":"Document 表示一篇原始文档（text + metadata），经 NodeParser 切分后得到若干 Node，Node 会继承 Document 的 metadata 并保留前后/父子关系。向量检索的最小单元是 Node 而不是 Document。"},{"id":"ch3-3.5-q3","chapter":"ch3","section":"3.5","type":"single","difficulty":2,"question":"用户要求「把这份 30 页的季度报告整体总结成 5 条要点」，最合适的索引类型是？","options":[{"key":"A","text":"VectorStoreIndex，语义检索最准"},{"key":"B","text":"KeywordTableIndex，关键词命中最快"},{"key":"C","text":"SummaryIndex，配合 tree_summarize 遍历全部 Node 聚合","correct":true},{"key":"D","text":"任何索引都可以，结果没有区别"}],"explanation":"全局总结类需求要求「看完所有内容」。VectorStoreIndex 只会返回 top-k 个相似片段，必然遗漏信息；SummaryIndex 顺序遍历全部 Node，配合 tree_summarize 自底向上归并，才是正确选择。"},{"id":"ch3-3.5-q4","chapter":"ch3","section":"3.5","type":"single","difficulty":3,"question":"句子窗口检索（SentenceWindowNodeParser）为什么要搭配 `MetadataReplacementPostProcessor` 使用？","options":[{"key":"A","text":"用于把 metadata 中的敏感字段脱敏后再返回给用户"},{"key":"B","text":"检索命中的是单句 Node，需要把内容替换成 metadata 里存的前后窗口，补足生成所需上下文","correct":true},{"key":"C","text":"用于把多个 Node 的 metadata 合并成一个，减少 token 消耗"},{"key":"D","text":"它负责重新计算相似度分数并对 Node 排序"}],"explanation":"句子窗口把「检索单元」和「生成单元」解耦：向量化用单句以提高命中精度，窗口（前后若干句）存在 Node 的 metadata 里。命中后必须用 MetadataReplacementPostProcessor 把 Node 内容替换成窗口文本，否则 LLM 只拿到孤立一句话，答不完整。"},{"id":"ch3-3.5-q5","chapter":"ch3","section":"3.5","type":"single","difficulty":3,"question":"线上 RAG 突然大面积答非所问，排查发现是有人把 `Settings.embed_model` 从 `text-embedding-3-small` 换成了另一个模型，但索引文件没有重建。最准确的解释是？","options":[{"key":"A","text":"只是生成质量下降，检索结果仍然正确，改回 response_mode 即可"},{"key":"B","text":"换 embedding 只影响速度不影响效果，真正原因应该在别处"},{"key":"C","text":"查询向量与索引中的向量来自不同模型、不在同一向量空间，相似度计算失去意义，召回近似随机，必须用新模型重建索引","correct":true},{"key":"D","text":"LlamaIndex 会自动检测并转换向量维度，不会有问题"}],"explanation":"向量检索的前提是查询向量和库中向量由**同一个 embedding 模型**产生，处于同一向量空间。换模型后即使维度恰好相同也不可比，相似度排序完全失效。唯一正确做法是用新模型重新跑一遍 ingestion 重建索引；这也是要把 embedding 模型名与索引一起版本化记录的原因。"},{"id":"ch3-3.5-q6","chapter":"ch3","section":"3.5","type":"single","difficulty":2,"question":"想只拿到检索结果做自定义处理、不让 LlamaIndex 调用 LLM 生成答案，应该用？","options":[{"key":"A","text":"`index.as_retriever().retrieve(q)` 或 `as_query_engine(response_mode=\"no_text\")`","correct":true},{"key":"B","text":"`index.as_query_engine(response_mode=\"refine\")`"},{"key":"C","text":"`index.as_chat_engine()` 并把 temperature 设为 0"},{"key":"D","text":"只能先生成答案，再从 response 里丢弃文本"}],"explanation":"Retriever 只负责召回、不调用 LLM，返回 List[NodeWithScore]；`response_mode=\"no_text\"` 同样跳过生成只返回 source_nodes。这两种方式都是评估召回质量时的标准做法，既快又不产生生成费用。"},{"id":"ch3-3.6-q2","chapter":"ch3","section":"3.6","type":"single","difficulty":2,"question":"关于 MCP 中 Host、Client、Server 三个角色，下列说法正确的是？","options":[{"key":"A","text":"一个 Client 可以同时连接多个 Server，从而减少连接数"},{"key":"B","text":"Client 与 Server 是 1:1 的关系，Host 连接 N 个 Server 就会持有 N 个 Client","correct":true},{"key":"C","text":"Server 需要知道 Host 使用的模型名称，才能生成合适的工具描述"},{"key":"D","text":"Host 就是 MCP Server 的另一种叫法，二者可以互换使用"}],"explanation":"MCP 规范中 Client 是宿主内部的协议连接器，与 Server 保持 1:1 的会话；Host 持有 LLM 推理循环并可同时管理多个 Client。Server 完全不感知宿主与模型，这正是解耦的意义。"},{"id":"ch3-3.6-q3","chapter":"ch3","section":"3.6","type":"single","difficulty":2,"question":"你要在 MCP Server 中暴露一份「服务限流配置」供模型参考，该配置只读、无副作用、可能被宿主反复读取。最合适的原语是？","options":[{"key":"A","text":"用 `@mcp.tool()` 定义一个 get_config 工具，让模型每轮自己调"},{"key":"B","text":"用 `@mcp.prompt()` 把配置内容拼进提示词模板"},{"key":"C","text":"用 `@mcp.resource(\"config://service/limits\")` 暴露为只读资源","correct":true},{"key":"D","text":"写进 Server 启动日志，让宿主从 stderr 里解析"}],"explanation":"Resources 的语义就是「只读、无副作用、由宿主/用户决定是否放入上下文」，类比 HTTP GET。做成 Tool 会白白消耗模型的调用轮次；Prompt 是给用户触发的模板，不适合承载数据。"},{"id":"ch3-3.6-q4","chapter":"ch3","section":"3.6","type":"single","difficulty":3,"question":"你的 stdio MCP Server 在 Inspector 里能正常跑，但被 Claude Desktop 加载后立刻断连，日志显示 JSON 解析错误。最可能的原因是？","options":[{"key":"A","text":"工具函数里用了 `print()` 往 stdout 打调试日志，污染了 JSON-RPC 通道","correct":true},{"key":"B","text":"没有为 Server 配置 OAuth 2.1 鉴权"},{"key":"C","text":"工具的 docstring 写得太短，模型无法识别"},{"key":"D","text":"没有调用 `session.initialize()` 完成握手"}],"explanation":"stdio 传输下 stdout 是协议通道，任何 print 都会混入 JSON-RPC 消息流导致解析失败、连接中断。日志必须写 stderr。B 只对远程传输有意义；C 不会导致断连；D 是客户端侧的职责，Inspector 已经能跑说明握手正常。"},{"id":"ch3-3.6-q5","chapter":"ch3","section":"3.6","type":"single","difficulty":2,"question":"在 FastMCP 中，工具函数因为「查询的文档不存在」而失败，推荐的处理方式是？","options":[{"key":"A","text":"调用 `sys.exit(1)` 让 Server 退出，由宿主重启"},{"key":"B","text":"直接 `raise ValueError(...)`，FastMCP 会返回 isError=True 的结果，模型可读到错误并重试","correct":true},{"key":"C","text":"返回空字符串，避免给模型造成困扰"},{"key":"D","text":"必须抛 `McpError`，否则连接会断开"}],"explanation":"业务级失败用普通异常即可，FastMCP 会捕获并封装成 isError=True 的工具结果，错误文本会回传给模型用于自我纠正。`McpError` 更适合参数非法等协议级错误（带标准错误码）。退出进程和静默返回空值都会让问题更难排查。"},{"id":"ch3-3.6-q6","chapter":"ch3","section":"3.6","type":"single","difficulty":3,"question":"团队要把一个内部订单查询能力开放给「自研 Agent + Claude Desktop + IDE 插件」三个宿主使用，且希望它独立部署、可单独审计。最合适的做法是？","options":[{"key":"A","text":"在三个宿主里各写一份 Function Calling 工具函数，保持各自灵活"},{"key":"B","text":"实现一个 MCP Server 并以 Streamable HTTP 传输部署，三个宿主通过各自的 MCP Client 接入","correct":true},{"key":"C","text":"只写一个 stdio MCP Server，让三个宿主分别把它当子进程拉起"},{"key":"D","text":"把订单能力做成某一个平台的私有插件，其他宿主通过爬取该平台调用"}],"explanation":"多宿主复用 + 独立部署 + 独立审计，正是 MCP 的典型收益场景；跨机房/跨应用访问需要远程传输，因此选 Streamable HTTP。A 退回 M×N 重复集成；C 的 stdio 无法做到独立部署与集中审计（每个宿主各起一份本地进程）；D 是明显的反模式。"},{"id":"ch3-3.7-q2","chapter":"ch3","section":"3.7","type":"single","difficulty":2,"question":"关于 Dify 与 Coze（扣子）的差异，下列说法最准确的是？","options":[{"key":"A","text":"Dify 只能做知识库问答，Coze 才能做 Agent"},{"key":"B","text":"Dify 开源且可完整自托管，适合数据不出内网的工程团队；Coze 的核心优势在插件市场与多渠道一键分发","correct":true},{"key":"C","text":"两者都完全闭源，只能通过 SaaS 使用"},{"key":"D","text":"Coze 支持工作流编排，Dify 只支持单轮问答，不能编排"}],"explanation":"两者的编排能力都不弱，本质差异在部署形态与生态：Dify 是开源项目，docker compose 即可完整私有化，适合有合规约束的企业；Coze 以 SaaS 托管为主（2025 年开源了 Coze Studio 社区版），真正的差异化价值是官方插件市场和一键发布到飞书、微信公众号、豆包等多个渠道。A、C、D 都与事实不符。"},{"id":"ch3-3.7-q3","chapter":"ch3","section":"3.7","type":"single","difficulty":2,"question":"某公司要做内部 SOP 知识问答，硬约束是「文档不得出内网」，团队有成熟的 K8s 运维能力，且业务方要求每条回答都能展示引用来源。按本节的决策路径，最合适的方案是？","options":[{"key":"A","text":"用 Coze 托管版快速搭建，把文档上传到平台知识库"},{"key":"B","text":"直接用 LangGraph 从零手写，因为低代码一定满足不了企业需求"},{"key":"C","text":"自托管 Dify 或 FastGPT，用其知识库能力并开启引用溯源","correct":true},{"key":"D","text":"用 Flowise 部署到生产，因为它是 Apache-2.0 协议"}],"explanation":"「数据不能出内网」直接排除 SaaS 托管方案（A）；有 K8s 运维能力则自托管无障碍，Dify 与 FastGPT 都开源可自托管且原生支持引用溯源，正是这条路径的终点（C）。B 属于过度工程，需求还没验证就投入手写成本；D 的问题不在协议而在生产化能力——Flowise 的多租户、权限与审计较弱，更适合原型和学习。"},{"id":"ch3-3.7-q4","chapter":"ch3","section":"3.7","type":"single","difficulty":3,"question":"你在自托管 Dify 上写脚本给知识库灌文档，调用 `POST /v1/datasets/{dataset_id}/document/create-by-text` 时始终返回 401，但同一份代码里调 `/v1/chat-messages` 却完全正常。最可能的原因是？","options":[{"key":"A","text":"知识库接口必须用 POST 之外的方法，应改成 PUT"},{"key":"B","text":"用了应用密钥（`app-` 开头）去调知识库接口，应改用知识库密钥（`dataset-` 开头）","correct":true},{"key":"C","text":"自托管版本不支持知识库 API，只有 SaaS 版才有"},{"key":"D","text":"请求体里缺少 `response_mode` 字段，导致鉴权失败"}],"explanation":"Dify 的密钥分两类且互不通用：应用密钥 `app-` 用于 `/chat-messages`、`/workflows/run` 等应用接口，知识库密钥 `dataset-` 用于 `/datasets/*` 系列接口。`/chat-messages` 能通恰恰说明你手里拿的是应用密钥，拿它打知识库接口必然 401。C 不成立（自托管同样提供知识库 API）；D 描述的是参数问题，会返回 400 而不是 401；A 纯属虚构。"},{"id":"ch3-3.7-q5","chapter":"ch3","section":"3.7","type":"single","difficulty":3,"question":"团队用低代码平台做了半年，现在出现「多人改同一个工作流互相覆盖」「改坏了线上才发现」两个问题。下列哪组「逃生舱」措施最对症？","options":[{"key":"A","text":"把工作流拆成更多小节点，并给每个节点加更长的备注"},{"key":"B","text":"立刻放弃低代码平台，整体用 LangGraph 重写"},{"key":"C","text":"定期导出 DSL 提交 Git 用 PR 评审，并维护黄金问答集用 API 跑批量回归、把命中率接进 CI","correct":true},{"key":"D","text":"换一个 UI 更好看的平台，并给每个人分配独立账号"}],"explanation":"两个问题分别对应「版本与协作弱」和「评测与回归缺失」。前者的标准解法是把工作流导出成文本 DSL 进 Git，借用成熟的 PR/diff/review 流程；后者的解法是黄金问答集 + 批量回归脚本 + CI 卡口，让每次改动都有数字兜底。A 只是加注释，救不了并发覆盖；B 是把洗澡水和孩子一起倒掉，成本过高；D 换平台不解决流程问题，独立账号也阻止不了同一个工作流被互相覆盖。"},{"id":"ch3-3.7-q6","chapter":"ch3","section":"3.7","type":"single","difficulty":2,"question":"需求是「每天早上 8 点自动拉取昨日工单系统数据，用 LLM 归类总结，写入表格并推送到群」。在本节介绍的平台里，最贴合这个需求的是？","options":[{"key":"A","text":"n8n，因为它以定时触发和数百个系统连接器见长，Agent 只是流程中的一环","correct":true},{"key":"B","text":"FastGPT，因为它的知识库能力最强"},{"key":"C","text":"Flowise，因为它基于 LangChain，功能最全"},{"key":"D","text":"Coze，因为它可以一键发布到多个渠道"}],"explanation":"这个需求的重心是「跨系统自动化 + 定时调度 + 失败重试」，LLM 只承担其中一步归类总结，正是 n8n 的主场（Cron 触发、数百个连接器、错误分支与重试）。B 的知识库能力在此用不上；C 偏原型与链式实验，调度与集成能力弱；D 的分发生态解决的是「机器人给谁用」，与定时 ETL 类需求不匹配。"},{"id":"ch3-3.8-q2","chapter":"ch3","section":"3.8","type":"single","difficulty":2,"question":"Agent 可观测性的三大支柱通常指？","options":[{"key":"A","text":"Traces / Metrics / Logs"},{"key":"B","text":"Traces / Metrics / Evals","correct":true},{"key":"C","text":"Logs / Metrics / Errors"},{"key":"D","text":"Traces / Logs / Evals"}],"explanation":"对 Agent 而言，可观测性三大支柱具体化为 Traces（链路）、Metrics（指标）、Evals（评估），Logs 虽重要但不属于这里强调的三支柱。"},{"id":"ch3-3.8-q3","chapter":"ch3","section":"3.8","type":"single","difficulty":2,"question":"在一次 Agent 调用中，每一个 LLM 调用、工具调用通常对应可观测性中的？","options":[{"key":"A","text":"一个 Trace"},{"key":"B","text":"一个 Span","correct":true},{"key":"C","text":"一个 Metric"},{"key":"D","text":"一个 Log"}],"explanation":"Trace 表示一次完整请求的端到端生命周期；其中的每个最小工作单元（LLM 调用、工具调用）是一个 Span。"},{"id":"ch3-3.8-q4","chapter":"ch3","section":"3.8","type":"single","difficulty":3,"question":"你在 LangSmith 中看不到任何 trace，最可能的原因是？","options":[{"key":"A","text":"没安装 langchain 包"},{"key":"B","text":"环境变量 LANGSMITH_TRACING 未设为 true","correct":true},{"key":"C","text":"Python 版本太低"},{"key":"D","text":"没有给函数加 @observe 装饰器"}],"explanation":"LangChain 的 LLM 调用在开启 LANGSMITH_TRACING=true 后会自动上报，无需 @observe 等埋点；看不到 trace 多半是 tracing 开关没打开或 API Key 缺失。"},{"id":"ch3-3.8-q5","chapter":"ch3","section":"3.8","type":"single","difficulty":2,"question":"OpenTelemetry / OpenLLMetry 相对 LangSmith / Langfuse 的主要优势是？","options":[{"key":"A","text":"只支持 LangChain 框架"},{"key":"B","text":"是开放标准，可接入既有 APM（Grafana/Jaeger）","correct":true},{"key":"C","text":"必须私有化部署"},{"key":"D","text":"是免费的 SaaS 服务"}],"explanation":"OpenTelemetry 是 CNCF 开放标准，OpenLLMetry 在其上提供 LLM 自动埋点，能把 LLM 调用汇入团队已有的 APM 体系，而非另起一套。"},{"id":"ch3-3.8-q6","chapter":"ch3","section":"3.8","type":"single","difficulty":3,"question":"评估 Agent 输出质量时，「LLM-as-judge」指的是？","options":[{"key":"A","text":"完全依赖人工标注"},{"key":"B","text":"用另一个 LLM 评判输出质量","correct":true},{"key":"C","text":"只做精确字符串匹配"},{"key":"D","text":"用单元测试断言"}],"explanation":"LLM-as-judge 是用一个（通常更强的）模型作为评委，对生成结果打分或判断好坏，适合开放式问答这类难以精确匹配的场景。"},{"id":"ch3-3.9-q2","chapter":"ch3","section":"3.9","type":"single","difficulty":2,"question":"团队用 Docker 沙箱执行 LLM 生成的代码，已经设置了 `mem_limit`、`pids_limit` 和 `user=nobody`。某次事故中，沙箱里的代码成功把宿主环境变量里的 API Key 发送到了外部服务器。最可能漏掉的是哪一项？","options":[{"key":"A","text":"没有设置 `read_only=True`"},{"key":"B","text":"没有设置 `network_disabled=True`（即 `--network none`）","correct":true},{"key":"C","text":"没有设置 `cap_drop=[\"ALL\"]`"},{"key":"D","text":"没有设置 `nano_cpus` 限制 CPU"}],"explanation":"数据外泄的必要条件是「能连出去」。`mem_limit`/`pids_limit` 管资源，`user=nobody` 管权限，都拦不住网络请求。只有禁网（`--network none`）才能从根上断掉外联通道。另外环境变量本身也不该继承宿主的，执行沙箱必须显式白名单传入环境变量。"},{"id":"ch3-3.9-q3","chapter":"ch3","section":"3.9","type":"single","difficulty":3,"question":"关于 RestrictedPython，下面哪个说法是**正确**的？","options":[{"key":"A","text":"它能阻止 `while True: pass` 这样的死循环耗尽 CPU"},{"key":"B","text":"它把代码放到独立进程执行，因此崩溃不影响主服务"},{"key":"C","text":"`import os` 之所以失败，是因为 `safe_builtins` 里没有 `__import__`，属于运行期拦截","correct":true},{"key":"D","text":"只要用了 `compile_restricted`，就不需要再替换 `__builtins__`"}],"explanation":"RestrictedPython 是**语言级**限制，代码仍在当前进程、当前解释器里跑，既挡不住死循环也挡不住内存耗尽（A、B 错）。它的防护是两层：编译期改写 AST（拒绝下划线开头的名字/属性）+ 运行期用安全的 `__builtins__` 和 guard 函数，两层缺一不可（D 错）。`import os` 语法上是合法的，失败发生在运行时找不到 `__import__`。"},{"id":"ch3-3.9-q4","chapter":"ch3","section":"3.9","type":"single","difficulty":3,"question":"【排查】用 `subprocess.Popen` + `communicate(timeout=5)` 实现沙箱，超时后调用了 `proc.kill()`。上线后发现机器上堆积了大量本该被杀掉的进程，CPU 长期打满。最可能的原因是？","options":[{"key":"A","text":"`timeout` 参数对 `communicate()` 不生效，要用 `wait(timeout=)`"},{"key":"B","text":"`proc.kill()` 只杀直接子进程，它 fork 出的孙进程会被 init 收养并继续运行","correct":true},{"key":"C","text":"`SIGKILL` 会被 Python 的信号处理器捕获并忽略"},{"key":"D","text":"`preexec_fn` 里设置的 `RLIMIT_CPU` 覆盖了 kill 行为"}],"explanation":"`proc.kill()` 只对直接子进程的 PID 生效。如果被执行的代码自己 `fork` 或 `Popen` 了新进程，父进程死后这些孙进程会被 PID 1 收养继续跑。正确做法是在 `preexec_fn` 里 `os.setsid()` 让子进程独立成组，超时时用 `os.killpg(os.getpgid(pid), SIGKILL)` 整组杀掉。`SIGKILL` 无法被捕获或忽略（C 错）。"},{"id":"ch3-3.9-q5","chapter":"ch3","section":"3.9","type":"single","difficulty":2,"question":"经典的 Python 沙箱逃逸链 `().__class__.__bases__[0].__subclasses__()` 利用的是什么？纯 AST 白名单方案是怎么堵住它的？","options":[{"key":"A","text":"利用 `eval` 的编译漏洞；靠限制表达式长度堵住"},{"key":"B","text":"利用属性穿透从任意对象拿到 `object` 的全部子类进而找到危险类；白名单直接不放行 `ast.Attribute` 节点","correct":true},{"key":"C","text":"利用元组的哈希碰撞；靠禁止元组字面量堵住"},{"key":"D","text":"利用 `__builtins__` 未清空；只要设 `{\"__builtins__\": {}}` 就完全安全了"}],"explanation":"这条链子从一个普通空元组出发，沿着 `__class__` → `__bases__` → `__subclasses__` 一路爬到 `object` 的所有子类，从中翻出能执行命令的类。它的每一步都是**属性访问**，所以只要白名单里不包含 `ast.Attribute`，整条链在语法检查阶段就被拒了。清空 `__builtins__` 是必要条件但不充分——正是因为有属性穿透，光清 builtins 并不安全。"},{"id":"ch3-3.9-q6","chapter":"ch3","section":"3.9","type":"single","difficulty":2,"question":"把沙箱接进 Agent 时，关于「代码执行工具」的输出处理，下面哪种做法最合理？","options":[{"key":"A","text":"只回传 stdout，执行出错时统一返回「执行失败」，避免泄露信息"},{"key":"B","text":"把 stdout 和 traceback 都截断后回传给模型，并限制重试次数","correct":true},{"key":"C","text":"完整回传 stdout 和 stderr，不做截断，保证模型拿到全部信息"},{"key":"D","text":"出错时自动换一个更强的模型重写代码，不设次数上限"}],"explanation":"「报错 → 模型自己改代码 → 重跑」是代码 Agent 最有价值的循环，所以错误信息必须回传（A 错），但要过滤掉宿主路径等环境信息。不截断则会被 `for i in range(10**7): print(i)` 这类输出瞬间撑爆上下文并烧掉大量 token（C 错）。无上限重试可能在一个装不上的包上无限打转（D 错）。"},{"id":"ch6-6.1-q2","chapter":"ch6","section":"6.1","type":"single","difficulty":1,"question":"最小 Agent 运行时「四件套」不包含以下哪项？","options":[{"key":"A","text":"调度器","correct":false},{"key":"B","text":"权限沙箱","correct":false},{"key":"C","text":"状态仓库","correct":false},{"key":"D","text":"编译器","correct":true}],"explanation":"四件套是调度器/权限沙箱/状态仓库/消息总线；编译器不是运行时的组成部分。"},{"id":"ch6-6.1-q3","chapter":"ch6","section":"6.1","type":"single","difficulty":2,"question":"「OS 给 Agent 用」与「Agent 组成 OS」的区别在于？","options":[{"key":"A","text":"前者人调度 Agent，后者 Agent 自组织","correct":true},{"key":"B","text":"前者更快后者更慢","correct":false},{"key":"C","text":"前者用 Linux 后者用 Windows","correct":false},{"key":"D","text":"两者完全等价","correct":false}],"explanation":"前者把 Agent 当受管负载跑在底座上（可控可审计），后者是大量自主 Agent 自组织成系统。"},{"id":"ch6-6.1-q4","chapter":"ch6","section":"6.1","type":"single","difficulty":2,"question":"在 Agent OS 中，传统 OS 的「地址空间保护」大致对应？","options":[{"key":"A","text":"进程调度","correct":false},{"key":"B","text":"权限沙箱","correct":true},{"key":"C","text":"文件系统","correct":false},{"key":"D","text":"IPC","correct":false}],"explanation":"权限沙箱限定每个 Agent 能触达的工具/数据，类比 OS 的地址空间保护。"},{"id":"ch6-6.1-q5","chapter":"ch6","section":"6.1","type":"single","difficulty":2,"question":"给运行时做「预算记账」的主要价值是？","options":[{"key":"A","text":"让代码跑得更快","correct":false},{"key":"B","text":"按 Agent 维度归因模型/工具成本","correct":true},{"key":"C","text":"替代单元测试","correct":false},{"key":"D","text":"减少代码行数","correct":false}],"explanation":"预算记账让每个 Agent 的 token/调用成本可归因，是治理与优化依据。"},{"id":"ch6-6.1-q6","chapter":"ch6","section":"6.1","type":"single","difficulty":1,"question":"以下哪项不是引入 Agent OS 的典型动机？","options":[{"key":"A","text":"资源争抢","correct":false},{"key":"B","text":"权限失控","correct":false},{"key":"C","text":"状态散落难恢复","correct":false},{"key":"D","text":"模型训练精度不足","correct":true}],"explanation":"三个典型痛点是资源争抢/权限失控/状态散落；模型精度是训练侧问题，不是运行时问题。"},{"id":"ch6-6.2-q1","chapter":"ch6","section":"6.2","type":"single","difficulty":1,"question":"具身智能区别于纯软件 Agent 的关键在于？","options":[{"key":"A","text":"用了更大的模型","correct":false},{"key":"B","text":"在物理/仿真世界里形成感知-行动闭环","correct":true},{"key":"C","text":"只处理文本","correct":false},{"key":"D","text":"不需要规划","correct":false}],"explanation":"具身 Agent 必须在环境中感知并行动，动作带来延迟/噪声/不可逆，这是与软件 Agent 的本质差异。"},{"id":"ch6-6.2-q2","chapter":"ch6","section":"6.2","type":"single","difficulty":2,"question":"把软件 Agent 直接搬到物理世界，通常不会踩到哪个坑？","options":[{"key":"A","text":"感知噪声与遮挡","correct":false},{"key":"B","text":"动作连续且不可逆","correct":false},{"key":"C","text":"模型参数量太小","correct":true},{"key":"D","text":"安全风险（撞坏设备/伤人）","correct":false}],"explanation":"物理世界的挑战在感知噪声、动作不可逆与安全，与模型参数量无直接关系。"},{"id":"ch6-6.2-q3","chapter":"ch6","section":"6.2","type":"single","difficulty":1,"question":"具身 Agent 最小控制循环的正确顺序是？","options":[{"key":"A","text":"感知→规划→执行→反馈","correct":true},{"key":"B","text":"执行→感知→规划→反馈","correct":false},{"key":"C","text":"规划→反馈→感知→执行","correct":false},{"key":"D","text":"反馈→执行→规划→感知","correct":false}],"explanation":"闭环是感知获取信息、规划决定动作、执行改变环境、反馈再次进入感知。"},{"id":"ch6-6.2-q4","chapter":"ch6","section":"6.2","type":"single","difficulty":2,"question":"VLA（Vision-Language-Action）模型指的是？","options":[{"key":"A","text":"把视觉-语言直接映射为动作","correct":true},{"key":"B","text":"三种独立模型拼接","correct":false},{"key":"C","text":"只做视觉识别","correct":false},{"key":"D","text":"一种数据库","correct":false}],"explanation":"VLA 把「看到的图像 + 听到的指令」直接映射为动作 token，是具身智能的主流范式之一。"},{"id":"ch6-6.2-q5","chapter":"ch6","section":"6.2","type":"single","difficulty":2,"question":"在具身 Agent 中引入 HITL（人在回路）的主要作用是？","options":[{"key":"A","text":"让机器人更慢","correct":false},{"key":"B","text":"对危险/不可逆动作做人工确认","correct":true},{"key":"C","text":"替代所有规划","correct":false},{"key":"D","text":"减少传感器数量","correct":false}],"explanation":"HITL 在不可逆或高风险动作前请人确认，是物理世界安全的兜底手段。"},{"id":"ch6-6.2-q6","chapter":"ch6","section":"6.2","type":"single","difficulty":1,"question":"sim-to-real 是指？","options":[{"key":"A","text":"从仿真训练迁移到真实机器人","correct":true},{"key":"B","text":"从真实到仿真","correct":false},{"key":"C","text":"模型量化","correct":false},{"key":"D","text":"数据加密","correct":false}],"explanation":"sim-to-real 指在仿真中学会策略，再迁移到真实机器人，降低真实环境试错成本。"},{"id":"ch6-6.3-q2","chapter":"ch6","section":"6.3","type":"single","difficulty":2,"question":"工程上默认更推荐哪条技术路线？","options":[{"key":"A","text":"端到端大模型（全塞进一个大模型）","correct":false},{"key":"B","text":"模块化 Agent 系统（模型只规划、工具外挂）","correct":true},{"key":"C","text":"两者都不行","correct":false},{"key":"D","text":"完全不用模型","correct":false}],"explanation":"只要场景要合规、可审计、能回滚，模块化系统更稳；端到端更适合探索性玩法。"},{"id":"ch6-6.3-q3","chapter":"ch6","section":"6.3","type":"single","difficulty":2,"question":"自改进 Agent 的核心元循环是？","options":[{"key":"A","text":"执行→自评→修订","correct":true},{"key":"B","text":"睡觉→做梦→醒来","correct":false},{"key":"C","text":"训练→部署→遗忘","correct":false},{"key":"D","text":"复制→粘贴→删除","correct":false}],"explanation":"自改进靠「执行产出→独立评测打分→把差距反馈修订」的闭环不断提升。"},{"id":"ch6-6.3-q4","chapter":"ch6","section":"6.3","type":"single","difficulty":2,"question":"「对齐（Alignment）」最贴切的理解是？","options":[{"key":"A","text":"让模型参数更多","correct":false},{"key":"B","text":"让 Agent 的目标与人类真实意图一致","correct":true},{"key":"C","text":"让回答更流畅","correct":false},{"key":"D","text":"让训练更快","correct":false}],"explanation":"对齐关注 Agent 是否在做「你想要的事」，尤其在目标模糊时不会精确而错误地完成。"},{"id":"ch6-6.3-q5","chapter":"ch6","section":"6.3","type":"single","difficulty":1,"question":"L4 自改进 Agent 的主要新增风险是？","options":[{"key":"A","text":"价值偏离（跑偏）","correct":true},{"key":"B","text":"响应太慢","correct":false},{"key":"C","text":"内存不足","correct":false},{"key":"D","text":"不支持中文","correct":false}],"explanation":"能力越强自主越高，若评测/目标有偏，可能「高效但错误地」偏离人类意图。"},{"id":"ch6-6.3-q6","chapter":"ch6","section":"6.3","type":"single","difficulty":2,"question":"关于「能力 vs 控制」，正确的是？","options":[{"key":"A","text":"能力越强越不需要控制","correct":false},{"key":"B","text":"能力越强越需要控制（权限/对齐/审计）","correct":true},{"key":"C","text":"控制只影响速度","correct":false},{"key":"D","text":"两者无关","correct":false}],"explanation":"Agent 能影响现实世界，能力增长会放大失控后果，因此控制必须同步加强。"},{"id":"ch6-6.4-q1","chapter":"ch6","section":"6.4","type":"single","difficulty":1,"question":"多模态 Agent 的输入/输出特点是？","options":[{"key":"A","text":"只有文本","correct":false},{"key":"B","text":"图/音/视频与文本混合","correct":true},{"key":"C","text":"只有图像","correct":false},{"key":"D","text":"只有语音","correct":false}],"explanation":"多模态 Agent 能处理文本、图像、音频、视频等多种通道的信息。"},{"id":"ch6-6.4-q2","chapter":"ch6","section":"6.4","type":"single","difficulty":1,"question":"多模态 Agent 的标准架构三段式是？","options":[{"key":"A","text":"编码→中枢→执行","correct":true},{"key":"B","text":"输入→睡觉→输出","correct":false},{"key":"C","text":"训练→推理→部署","correct":false},{"key":"D","text":"加密→传输→解密","correct":false}],"explanation":"模态编码层把图/音/视频转成表示，中枢 MLLM 理解规划，执行层调工具/生成。"},{"id":"ch6-6.4-q3","chapter":"ch6","section":"6.4","type":"single","difficulty":2,"question":"用 gpt-4o 做图像理解时，正确的输入方式是？","options":[{"key":"A","text":"image_url + base64 编码","correct":true},{"key":"B","text":"把图片路径当纯文本发","correct":false},{"key":"C","text":"只发文件名","correct":false},{"key":"D","text":"不需要编码","correct":false}],"explanation":"gpt-4o 原生支持 image_url 类型，图片以 data URL（base64）形式传入。"},{"id":"ch6-6.4-q4","chapter":"ch6","section":"6.4","type":"single","difficulty":1,"question":"多模态落地的工程挑战不包括？","options":[{"key":"A","text":"模态对齐","correct":false},{"key":"B","text":"延迟","correct":false},{"key":"C","text":"成本","correct":false},{"key":"D","text":"模型不能写诗","correct":true}],"explanation":"对齐/延迟/成本是真实挑战；「不能写诗」不是工程问题。"},{"id":"ch6-6.4-q5","chapter":"ch6","section":"6.4","type":"single","difficulty":2,"question":"「别让模型看戏」的含义是？","options":[{"key":"A","text":"先用 OCR/裁剪拿到关键区再送模型","correct":true},{"key":"B","text":"不让模型看图片","correct":false},{"key":"C","text":"把模型关掉","correct":false},{"key":"D","text":"只发整张图","correct":false}],"explanation":"很多场景只需关键字段，先裁剪/OCR 再送模型，成本与延迟都能大幅下降。"},{"id":"ch6-6.4-q6","chapter":"ch6","section":"6.4","type":"single","difficulty":2,"question":"为降低多模态成本，最合理的做法是？","options":[{"key":"A","text":"只把必要帧/区域送模型，文本能解的不上图","correct":true},{"key":"B","text":"永远发整张高清图","correct":false},{"key":"C","text":"完全不用多模态","correct":false},{"key":"D","text":"只发视频不发文本","correct":false}],"explanation":"按需送最小必要信息，是平衡效果与成本的关键工程原则。"},{"id":"ch6-6.5-q2","chapter":"ch6","section":"6.5","type":"single","difficulty":2,"question":"防护「四件套」指的是？","options":[{"key":"A","text":"最小权限+沙箱+HITL+审计日志","correct":true},{"key":"B","text":"四个模型","correct":false},{"key":"C","text":"四种提示词","correct":false},{"key":"D","text":"四个数据库","correct":false}],"explanation":"四件套对应四类风险：权限过大/越权破坏/不可逆操作/事后追溯。"},{"id":"ch6-6.5-q3","chapter":"ch6","section":"6.5","type":"single","difficulty":2,"question":"护栏（guardrail）最应该包在哪儿？","options":[{"key":"A","text":"包在工具外面，统一做权限/敏感拦截","correct":true},{"key":"B","text":"包在模型内部","correct":false},{"key":"C","text":"不需要","correct":false},{"key":"D","text":"只包在日志里","correct":false}],"explanation":"把护栏放在工具外层，可横切到所有 Agent，与业务解耦、易复用。"},{"id":"ch6-6.5-q4","chapter":"ch6","section":"6.5","type":"single","difficulty":1,"question":"「提示注入」是指？","options":[{"key":"A","text":"外部内容里藏指令劫持 Agent","correct":true},{"key":"B","text":"模型自己写错字","correct":false},{"key":"C","text":"网络延迟","correct":false},{"key":"D","text":"数据库连接失败","correct":false}],"explanation":"攻击者在网页/邮件/文档中嵌入指令，间接操控 Agent 偏离原意。"},{"id":"ch6-6.5-q5","chapter":"ch6","section":"6.5","type":"single","difficulty":2,"question":"对于转账、删除等敏感操作，正确做法是？","options":[{"key":"A","text":"默认挂起 + 人工确认 + 审计留痕","correct":true},{"key":"B","text":"AI 自作主张直接执行","correct":false},{"key":"C","text":"完全禁止一切操作","correct":false},{"key":"D","text":"只记录不确认","correct":false}],"explanation":"敏感操作应默认挂起、需显式确认并留痕，从接口层杜绝越权执行。"},{"id":"ch6-6.5-q6","chapter":"ch6","section":"6.5","type":"single","difficulty":2,"question":"红队评测集（注入/越权测试）的目的是？","options":[{"key":"A","text":"主动攻击验证护栏是否真的有效","correct":true},{"key":"B","text":"让模型更慢","correct":false},{"key":"C","text":"减少代码量","correct":false},{"key":"D","text":"替代单元测试","correct":false}],"explanation":"安全要主动攻防，把注入/越权用例并入 CI，每次改动都重跑。"},{"id":"ch6-6.6-q1","chapter":"ch6","section":"6.6","type":"single","difficulty":1,"question":"「Agent 经济」的核心意象是？","options":[{"key":"A","text":"Agents 作为自主市场主体去发现、协商、交易","correct":true},{"key":"B","text":"卖更多显卡","correct":false},{"key":"C","text":"只做免费开源","correct":false},{"key":"D","text":"关闭所有 API","correct":false}],"explanation":"Agent 经济里 Agent 能自动发现需求、协商价格、调用彼此并结算。"},{"id":"ch6-6.6-q2","chapter":"ch6","section":"6.6","type":"single","difficulty":2,"question":"Agent 服务市场里被交易的主要是？","options":[{"key":"A","text":"可发现、可计费的「能力单元」（函数/模型/工具）","correct":true},{"key":"B","text":"只有整机服务器","correct":false},{"key":"C","text":"只有域名","correct":false},{"key":"D","text":"只有论文","correct":false}],"explanation":"市场把翻译、合规检查、行业模型等能力单元自描述、按需计费地暴露。"},{"id":"ch6-6.6-q3","chapter":"ch6","section":"6.6","type":"single","difficulty":2,"question":"与传统 SaaS 相比，Agent 经济的关键不同是？","options":[{"key":"A","text":"按能力/调用计费且 Agent 自主协商","correct":true},{"key":"B","text":"仍然按月固定订阅、人手动集成","correct":false},{"key":"C","text":"更贵的硬件","correct":false},{"key":"D","text":"不支持 API","correct":false}],"explanation":"Agent 经济把集成与计费自动化，能力按需调用、按结果微支付。"},{"id":"ch6-6.6-q4","chapter":"ch6","section":"6.6","type":"single","difficulty":2,"question":"Agent 经济的信任基础设施不包括？","options":[{"key":"A","text":"身份与授权","correct":false},{"key":"B","text":"可验证执行","correct":false},{"key":"C","text":"支付与争议处理","correct":false},{"key":"D","text":"强制每天发邮件","correct":true}],"explanation":"信任层来自身份/可验证执行/支付仲裁；发邮件不是基础设施。"},{"id":"ch6-6.6-q5","chapter":"ch6","section":"6.6","type":"single","difficulty":1,"question":"按调用计费（pay-per-call）实现的关键是？","options":[{"key":"A","text":"调用前验余额、扣费并记账","correct":true},{"key":"B","text":"月底一次性猜账","correct":false},{"key":"C","text":"不记账","correct":false},{"key":"D","text":"只收现金","correct":false}],"explanation":"计费内核是「调用前校验余额→扣费→入账本」，保证可审计。"},{"id":"ch6-6.6-q6","chapter":"ch6","section":"6.6","type":"single","difficulty":2,"question":"没有结算基础设施，Agent 经济会怎样？","options":[{"key":"A","text":"无法计费与验证，市场无从形成（白嫖/互坑）","correct":true},{"key":"B","text":"反而更繁荣","correct":false},{"key":"C","text":"模型会更快","correct":false},{"key":"D","text":"没有影响","correct":false}],"explanation":"先有账本与验证，才有可信交易；否则市场难以自组织。"},{"id":"ch6-6.7-q1","chapter":"ch6","section":"6.7","type":"single","difficulty":1,"question":"MCP（Model Context Protocol）主要解决？","options":[{"key":"A","text":"让工具以统一协议接入任意模型/Agent","correct":true},{"key":"B","text":"让 Agent 之间聊天","correct":false},{"key":"C","text":"训练大模型","correct":false},{"key":"D","text":"做数据库迁移","correct":false}],"explanation":"MCP 是工具侧互操作标准，类比 USB 接口，让能力可移植。"},{"id":"ch6-6.7-q2","chapter":"ch6","section":"6.7","type":"single","difficulty":1,"question":"A2A 协议主要解决？","options":[{"key":"A","text":"不同 Agent 之间互相发现与通信","correct":true},{"key":"B","text":"图片压缩","correct":false},{"key":"C","text":"模型量化","correct":false},{"key":"D","text":"写前端样式","correct":false}],"explanation":"A2A 让异构 Agent 能彼此协作，类似 Agent 间的通信协议。"},{"id":"ch6-6.7-q3","chapter":"ch6","section":"6.7","type":"single","difficulty":2,"question":"本地开源模型（如通过 Ollama 运行 Qwen）对构建者的主要价值是？","options":[{"key":"A","text":"降本 + 数据不出域 + 可控","correct":true},{"key":"B","text":"一定比云端更强","correct":false},{"key":"C","text":"不需要任何接口","correct":false},{"key":"D","text":"只能离线写诗","correct":false}],"explanation":"本地模型在成本、隐私、可控上有红利，适合高频简单或敏感任务。"},{"id":"ch6-6.7-q4","chapter":"ch6","section":"6.7","type":"single","difficulty":2,"question":"面对「框架爆炸」，最稳的跟进策略是？","options":[{"key":"A","text":"固定信源 + 建评估集 + 按任务取舍","correct":true},{"key":"B","text":"每个新框架都立刻全量采用","correct":false},{"key":"C","text":"只看热榜决定技术栈","correct":false},{"key":"D","text":"完全不关注生态","correct":false}],"explanation":"让评估集说话、做减法，比追热榜更可持续。"},{"id":"ch6-6.7-q5","chapter":"ch6","section":"6.7","type":"single","difficulty":2,"question":"关于框架选型，正确的是？","options":[{"key":"A","text":"先想清要编排/检索/多Agent协同，再选对应框架","correct":true},{"key":"B","text":"哪个最火用哪个","correct":false},{"key":"C","text":"框架越多越好","correct":false},{"key":"D","text":"完全不需要框架","correct":false}],"explanation":"框架侧重不同，先明确任务类型再匹配，避免混用增熵。"},{"id":"ch6-6.7-q6","chapter":"ch6","section":"6.7","type":"single","difficulty":1,"question":"混合路由（本地+云端）的核心决策维度通常是？","options":[{"key":"A","text":"敏感度与复杂度","correct":true},{"key":"B","text":"模型颜色","correct":false},{"key":"C","text":"星期几","correct":false},{"key":"D","text":"随机数","correct":false}],"explanation":"用「是否敏感、是否复杂」双维度路由，兼顾成本、隐私与能力。"},{"id":"ch6-6.8-q1","chapter":"ch6","section":"6.8","type":"single","difficulty":1,"question":"前六章建议的学习顺序是？","options":[{"key":"A","text":"基础→框架→多Agent→行业→安全→趋势","correct":true},{"key":"B","text":"趋势→安全→行业→多Agent→框架→基础","correct":false},{"key":"C","text":"随便跳着看","correct":false},{"key":"D","text":"只看第 6 章","correct":false}],"explanation":"路径由地基到上层：概念→实战→系统设计→落地→安全→趋势回望。"},{"id":"ch6-6.8-q2","chapter":"ch6","section":"6.8","type":"single","difficulty":2,"question":"动手项目的最佳进阶是？","options":[{"key":"A","text":"最小 Agent→加记忆/RAG→多Agent→带 HITL+评估集上线","correct":true},{"key":"B","text":"直接上线最复杂的系统","correct":false},{"key":"C","text":"只读书不写码","correct":false},{"key":"D","text":"抄别人的成品","correct":false}],"explanation":"循序渐进，每一步都有可运行产物，最后才上生产级能力。"},{"id":"ch6-6.8-q3","chapter":"ch6","section":"6.8","type":"single","difficulty":2,"question":"社区与持续成长的关键习惯是？","options":[{"key":"A","text":"保持亲手做 + 写笔记 + 建评估集","correct":true},{"key":"B","text":"只收藏不实践","correct":false},{"key":"C","text":"追每个新名词","correct":false},{"key":"D","text":"闭门造车","correct":false}],"explanation":"真正成长来自改坏一次、修好一次、写进评估集；少收藏多动手。"},{"id":"ch6-6.8-q4","chapter":"ch6","section":"6.8","type":"single","difficulty":2,"question":"为第一个 Agent 建「评估集」的主要作用是？","options":[{"key":"A","text":"作为回归基准，防止后续改动退化","correct":true},{"key":"B","text":"凑字数","correct":false},{"key":"C","text":"替代代码","correct":false},{"key":"D","text":"给老板看","correct":false}],"explanation":"评估集是回归基准，任何改动都重跑，保障能力不退化。"},{"id":"ch6-6.8-q5","chapter":"ch6","section":"6.8","type":"single","difficulty":1,"question":"能力地图里强制写「evidence（证据）」字段的意义是？","options":[{"key":"A","text":"强制拿得出成果，避免目标流于口号","correct":true},{"key":"B","text":"凑长度","correct":false},{"key":"C","text":"给模型看","correct":false},{"key":"D","text":"无意义","correct":false}],"explanation":"evidence 字段要求「拿出成果」，把进度从自我安慰变成可验证。"},{"id":"ch6-6.8-q6","chapter":"ch6","section":"6.8","type":"single","difficulty":1,"question":"ROADMAP 进度追踪器的主要价值是？","options":[{"key":"A","text":"把学习变可勾选清单，进度一目了然","correct":true},{"key":"B","text":"让学习更慢","correct":false},{"key":"C","text":"替代课程","correct":false},{"key":"D","text":"没有价值","correct":false}],"explanation":"可勾选清单提供即时反馈，避免「学了很多却没落地」。"}],"chapterQuizzes":[{"id":"ch1-final","title":"第 1 章综合测验 - 基础概念入门","questions":["ch1-1.1-q1","ch1-1.1-q2","ch1-1.2-q1","ch1-1.2-q2","ch1-1.3-q1","ch1-1.3-q2","ch1-1.4-q1","ch1-1.4-q2","ch1-1.5-q1","ch1-1.6-q1"],"passingScore":70},{"id":"ch2-final","title":"第 2 章综合测验 - 核心原理深入","questions":["ch2-2.1-q1","ch2-2.1-q2","ch2-2.2-q1","ch2-2.2-q2","ch2-2.3-q1","ch2-2.4-q1","ch2-2.4-q2","ch2-2.6-q1","ch2-2.8-q1","ch2-2.8-q2"],"passingScore":70},{"id":"ch3-final","title":"第 3 章综合测验 - 框架与工具实战","questions":["ch3-3.1-q1","ch3-3.1-q2","ch3-3.2-q1","ch3-3.3-q1","ch3-3.6-q1","ch3-3.8-q1","ch3-3.4-q1","ch3-3.5-q1","ch3-3.7-q1","ch3-3.9-q1"],"passingScore":70},{"id":"ch4-final","title":"第 4 章综合测验 - 多 Agent 系统设计","questions":["ch4-4.1-q1","ch4-4.1-q2","ch4-4.4-q1","ch4-4.7-q1","ch4-4.2-q1","ch4-4.3-q1","ch4-4.5-q1","ch4-4.6-q1","ch4-4.8-q1"],"passingScore":70},{"id":"ch5-final","title":"第 5 章综合测验 - 行业应用与最佳实践","questions":["ch5-5.1-q1","ch5-5.3-q1","ch5-5.8-q1","ch5-5.9-q1","ch5-5.10-q1"],"passingScore":70},{"id":"ch6-final","title":"第 6 章综合测验 - 前沿趋势展望","questions":["ch6-6.1-q1","ch6-6.1-q2","ch6-6.1-q3","ch6-6.1-q4","ch6-6.1-q5","ch6-6.1-q6","ch6-6.2-q1","ch6-6.2-q2","ch6-6.2-q3","ch6-6.2-q4","ch6-6.2-q5","ch6-6.2-q6","ch6-6.3-q1","ch6-6.3-q2","ch6-6.3-q3","ch6-6.3-q4","ch6-6.3-q5","ch6-6.3-q6","ch6-6.4-q1","ch6-6.4-q2","ch6-6.4-q3","ch6-6.4-q4","ch6-6.4-q5","ch6-6.4-q6","ch6-6.5-q1","ch6-6.5-q2","ch6-6.5-q3","ch6-6.5-q4","ch6-6.5-q5","ch6-6.5-q6","ch6-6.6-q1","ch6-6.6-q2","ch6-6.6-q3","ch6-6.6-q4","ch6-6.6-q5","ch6-6.6-q6","ch6-6.7-q1","ch6-6.7-q2","ch6-6.7-q3","ch6-6.7-q4","ch6-6.7-q5","ch6-6.7-q6","ch6-6.8-q1","ch6-6.8-q2","ch6-6.8-q3","ch6-6.8-q4","ch6-6.8-q5","ch6-6.8-q6"]}]};

